window.WPS = window.WPS || {};
WPS.RONJUTSU = [
  // ===== 日本史 =====
  { id: 'j01', s: 'jh', lv: 1, topic: '班田収授法', q: '律令制のもとで、班田収授法は何を目的としていたか。', a: '【戸籍】にもとづいて6歳以上の男女に【口分田】を与え、死後に返させることで、【租】などの税を確実に集めることを目的とした。' },
  { id: 'j02', s: 'jh', lv: 1, topic: '墾田永年私財法', q: '墾田永年私財法（743年）は、土地制度にどのような変化をもたらしたか。', a: '開墾した土地の【私有】を永久に認めたため、貴族や寺社が開墾を進めて【荘園】が広がり、【公地公民】の原則がくずれていった。' },
  { id: 'j03', s: 'jh', lv: 1, topic: '摂関政治', q: '藤原氏は、どのようにして摂関政治の実権を手に入れたか。', a: '娘を天皇の【后】にして、生まれた子を天皇に立てた。天皇の【外戚】として【摂政】や【関白】の地位につき、政治の実権をにぎった。' },
  { id: 'j04', s: 'jh', lv: 1, topic: '院政', q: '院政とはどのような政治か。始めた人物とともに説明せよ。', a: '天皇が位をゆずって【上皇】となったあとも、【院庁】を中心に政治を行うしくみで、1086年に【白河上皇】が始めた。' },
  { id: 'j05', s: 'jh', lv: 1, topic: '御恩と奉公', q: '鎌倉幕府の将軍と御家人の関係を説明せよ。', a: '将軍は御家人の領地を保障したり新しい領地を与えたりする【御恩】を与え、御家人は戦いや警備で【奉公】した。【土地】を仲立ちとしたこの主従関係を【封建制度】という。' },
  { id: 'j06', s: 'jh', lv: 2, topic: '元寇', q: '元寇（蒙古襲来）は、鎌倉幕府の衰退にどうつながったか。', a: '防衛戦では新しい領地が得られず、御家人に十分な【恩賞】を与えられなかった。【分割相続】で困窮していた御家人を救うため【徳政令】を出したが効果は小さく、幕府は信頼を失った。' },
  { id: 'j07', s: 'jh', lv: 2, topic: '日明貿易', q: '足利義満が始めた日明貿易で、勘合が用いられた理由を述べよ。', a: '正式な貿易船と【倭寇】を区別するため、明が与えた【勘合】という合い札を用いた。この貿易は【朝貢】の形式で行われた。' },
  { id: 'j08', s: 'jh', lv: 1, topic: '太閤検地', q: '太閤検地は、社会にどのような変化をもたらしたか。', a: '全国の土地を統一した基準で調べ、生産力を【石高】で表した。耕作者を【検地帳】に登録して年貢の負担者とし、【荘園】のしくみは完全にくずれた。' },
  { id: 'j09', s: 'jh', lv: 2, topic: '刀狩', q: '豊臣秀吉の刀狩の目的と結果を述べよ。', a: '農民から武器を取り上げて【一揆】を防ぎ、農業に専念させた。太閤検地とあわせて、武士と農民の身分を分ける【兵農分離】が進んだ。' },
  { id: 'j10', s: 'jh', lv: 1, topic: '参勤交代', q: '参勤交代は、大名や社会にどのような影響を与えたか。', a: '大名は1年おきに【江戸】と領地を行き来し、妻子は江戸に住まわされた。多額の【出費】で大名の力が弱まる一方、【街道】や宿場町が発達した。' },
  { id: 'j11', s: 'jh', lv: 2, topic: '鎖国', q: '江戸幕府が貿易の相手を限った理由と、その相手を述べよ。', a: '【キリスト教】の広まりを防ぎ、貿易の利益を幕府が独占するため、長崎で【オランダ】と【中国】に限って貿易を認めた。' },
  { id: 'j12', s: 'jh', lv: 2, topic: '享保の改革', q: '徳川吉宗の享保の改革で行われた政策を述べよ。', a: '大名に米を納めさせる【上げ米】を行い、【新田開発】を進めて年貢を増やした。また【公事方御定書】で裁判の基準を定めた。' },
  { id: 'j13', s: 'jh', lv: 2, topic: '田沼の政治', q: '田沼意次の政治の特徴を述べよ。', a: '商人の経済力を利用し、【株仲間】の結成を認めて営業税を取り、【長崎貿易】を拡大した。一方で【わいろ】が横行したと批判された。' },
  { id: 'j14', s: 'jh', lv: 1, topic: '地租改正', q: '地租改正の内容と目的を述べよ。', a: '土地の所有者に【地券】を発行し、【地価】の3%を【現金】で納めさせた。収穫に左右されない、安定した税収を得ることが目的だった。' },
  { id: 'j15', s: 'jh', lv: 2, topic: '自由民権運動', q: '自由民権運動はどのように始まり、何を求めたか。', a: '板垣退助らが【民撰議院設立建白書】を提出して始まり、【国会】の開設や憲法の制定を求めた。政府は1881年に【国会開設の勅諭】を出した。' },
  { id: 'j16', s: 'jh', lv: 2, topic: '条約改正', q: '不平等条約の改正はどのように進んだか。', a: '1894年に【陸奥宗光】が【領事裁判権】の撤廃に成功し、1911年に【小村寿太郎】が【関税自主権】の回復を実現した。' },
  { id: 'j17', s: 'jh', lv: 3, topic: '三国干渉', q: '日清戦争後の三国干渉は、日本にどのような影響を与えたか。', a: '【下関条約】で得た【遼東半島】を、ロシア・ドイツ・フランスの勧告で清に返した。国民のあいだに【ロシア】への反感が高まり、「臥薪嘗胆」を合言葉に【軍備拡張】が進んだ。' },
  { id: 'j18', s: 'jh', lv: 2, topic: '普通選挙法', q: '1925年の普通選挙法と治安維持法は、どのような関係にあるか。', a: '普通選挙法で【満25歳以上の男子】に選挙権が与えられた。同じ年に【治安維持法】を定め、選挙権の拡大で勢いづくおそれのある【共産主義】などの運動を取り締まった。' },
  { id: 'j19', s: 'jh', lv: 3, topic: '満州事変', q: '昭和恐慌は、満州事変にどうつながったか。', a: '【世界恐慌】の影響で農村が深刻な不況におちいり、政党政治への不信が高まった。軍部は【満州】に活路を求め、1931年に【柳条湖事件】を起こして満州事変を始めた。' },
  { id: 'j20', s: 'jh', lv: 1, topic: '農地改革', q: '戦後の農地改革の内容と結果を述べよ。', a: '政府が【地主】の土地を買い上げて【小作人】に安く売り渡し、多くの【自作農】が生まれた。' },
  { id: 'j21', s: 'jh', lv: 2, topic: '高度経済成長', q: '高度経済成長期には、どのような社会問題が生じたか。', a: '工業化が急速に進んだ結果、【公害】が各地で発生し、【四大公害】訴訟が起こった。政府は1967年に【公害対策基本法】を定めた。' },
  { id: 'j22', s: 'jh', lv: 3, topic: '鎌倉新仏教', q: '鎌倉時代に新しい仏教が広まった理由を述べよ。', a: '戦乱やききんで不安が高まる中、【念仏】や【題目】を唱えるなど、わかりやすく実践しやすい教えが示されたため、【武士】や【庶民】に広まった。' },
  { id: 'j23', s: 'jh', lv: 3, topic: '応仁の乱', q: '応仁の乱は、戦国時代の始まりにどうつながったか。', a: '【将軍】のあとつぎ争いに有力【守護大名】の対立が結びついて11年続き、幕府の権威が衰えた。その結果、実力で領国を支配する【戦国大名】が各地に現れた（【下剋上】）。' },
  { id: 'j24', s: 'jh', lv: 3, topic: '天保の改革', q: '水野忠邦の天保の改革が失敗した理由を述べよ。', a: '【株仲間】を解散させたが物価は下がらず、かえって流通が混乱した。江戸・大坂周辺を幕府領にしようとした【上知令】も大名や旗本の反対で撤回され、忠邦は【失脚】した。' },
  // ===== 世界史 =====
  { id: 'w01', s: 'wh', lv: 1, topic: '大運河', q: '隋が建設した大運河は、中国の経済にどのような役割を果たしたか。', a: '【華北】と【江南】を結び、江南でとれた【穀物】を北方の都へ大量に運んだ。豊かな南方の【経済力】が王朝の政治と軍事を支えた。' },
  { id: 'w02', s: 'wh', lv: 1, topic: 'ローマの平和', q: '「ローマの平和」とよばれる時代の特徴を述べよ。', a: '【アウグストゥス】が帝政を始めてから約200年間、地中海世界が政治的に安定した（【パクス=ロマーナ】）。【道路網】の整備などで交易が栄えた。' },
  { id: 'w03', s: 'wh', lv: 1, topic: '十字軍', q: '十字軍の遠征は、ヨーロッパ社会にどのような影響を与えたか。', a: '遠征の失敗で【教皇】の権威が低下し、多くの【諸侯】や騎士が没落した。一方で【東方貿易】がさかんになり、イタリアの諸都市が栄えた。' },
  { id: 'w04', s: 'wh', lv: 2, topic: 'ルネサンス', q: 'ルネサンスがイタリアで始まった理由を述べよ。', a: '東方貿易で栄えた都市に富が集まり、【メディチ家】などの有力者が芸術を保護した。また古代【ギリシア・ローマ】の文化遺産が身近にあり、【ビザンツ帝国】から学者も流入した。' },
  { id: 'w05', s: 'wh', lv: 1, topic: '宗教改革', q: 'ルターが宗教改革を始めたきっかけと、その主張を述べよ。', a: '教皇による【贖宥状】の販売を批判し、1517年に【九十五か条の論題】を発表した。人は【信仰】によってのみ救われ、【聖書】だけが信仰のよりどころだと説いた。' },
  { id: 'w06', s: 'wh', lv: 2, topic: '大航海時代', q: '大航海時代は、ヨーロッパ経済にどのような影響を与えたか。', a: '新航路の開拓で、交易の中心が地中海から【大西洋】沿岸に移った（【商業革命】）。またアメリカ大陸から大量の【銀】が流入し、物価が大きく上がった（【価格革命】）。' },
  { id: 'w07', s: 'wh', lv: 2, topic: '名誉革命', q: '名誉革命の結果、イギリスの政治はどう変わったか。', a: '議会が新しい国王を迎え、【権利の章典】で国王の権力を制限した。これにより【議会】が政治の中心となる【立憲君主制】が確立した。' },
  { id: 'w08', s: 'wh', lv: 1, topic: '産業革命', q: 'イギリスで最初に産業革命が起こった理由を述べよ。', a: '植民地による広い【市場】と原料があったこと、【囲い込み】で生まれた労働力があったこと、【石炭】や鉄などの資源が豊かだったことがあげられる。' },
  { id: 'w09', s: 'wh', lv: 2, topic: 'アメリカ独立革命', q: 'アメリカ独立革命の原因を述べよ。', a: '七年戦争後、財政難のイギリスが【印紙法】などで植民地に課税した。植民地側は「【代表なくして課税なし】」と反発し、1776年に【独立宣言】を発表した。' },
  { id: 'w10', s: 'wh', lv: 1, topic: 'フランス革命', q: 'フランス革命が起こった社会的背景を述べよ。', a: '聖職者の【第一身分】と貴族の【第二身分】は免税などの特権をもち、人口の大部分をしめる【第三身分】が重い負担を負っていた。この【旧体制】への不満が革命につながった。' },
  { id: 'w11', s: 'wh', lv: 2, topic: 'ナポレオン', q: 'ナポレオンの支配は、ヨーロッパにどのような影響を与えたか。', a: '【ナポレオン法典】で法の下の平等など革命の理念を広めた。一方、征服された地域では【ナショナリズム】が高まり、各地で抵抗が起こった。' },
  { id: 'w12', s: 'wh', lv: 3, topic: 'ウィーン体制', q: 'ウィーン体制の基本原則と、崩壊のきっかけを述べよ。', a: 'フランス革命前の王朝と秩序を回復する【正統主義】と、大国の【勢力均衡】を原則とした。しかし【自由主義】やナショナリズムの運動が広がり、1848年の【二月革命】などで崩壊した。' },
  { id: 'w13', s: 'wh', lv: 2, topic: 'アヘン戦争', q: 'アヘン戦争の原因と結果を述べよ。', a: 'イギリスは【茶】の輸入で生じた赤字を補うため、インド産の【アヘン】を清に密輸した。清が取り締まると戦争になり、敗れた清は【南京条約】で香港を割譲し、5港を開いた。' },
  { id: 'w14', s: 'wh', lv: 3, topic: '辛亥革命', q: '辛亥革命は、どのような経過で清朝を倒したか。', a: '1911年に【武昌】で軍隊が蜂起すると各省が独立を宣言し、1912年に【孫文】を臨時大総統とする【中華民国】が成立した。清の実力者【袁世凱】が皇帝を退位させ、清は滅んだ。' },
  { id: 'w15', s: 'wh', lv: 1, topic: '第一次世界大戦', q: '第一次世界大戦は、どのように始まったか。', a: '1914年、オーストリアの帝位継承者夫妻が【サライェヴォ】で暗殺された。これをきっかけに、【三国同盟】側と【三国協商】側の対立が戦争に発展した。' },
  { id: 'w16', s: 'wh', lv: 2, topic: 'ヴェルサイユ条約', q: 'ヴェルサイユ条約は、ドイツにどのような影響を与えたか。', a: 'ドイツはすべての植民地を失い、巨額の【賠償金】と【軍備制限】を課された。国民の不満は高まり、のちに【ナチス】が台頭する一因となった。' },
  { id: 'w17', s: 'wh', lv: 1, topic: 'ニューディール', q: '世界恐慌に対して、アメリカはどのような政策をとったか。', a: '【フランクリン=ローズヴェルト】大統領が【ニューディール】政策を行った。【TVA】などの公共事業で失業者を雇うなど、政府が経済に積極的に関わった。' },
  { id: 'w18', s: 'wh', lv: 2, topic: 'ブロック経済', q: '世界恐慌後のブロック経済は、国際関係にどう影響したか。', a: 'イギリスやフランスは本国と植民地で【ブロック経済】をつくり、外国製品に高い【関税】をかけた。植民地の少ないドイツ・イタリア・日本は対外進出を強め、【第二次世界大戦】の一因となった。' },
  { id: 'w19', s: 'wh', lv: 1, topic: '冷戦', q: '冷戦とはどのような対立か。', a: '第二次世界大戦後の、【アメリカ】を中心とする資本主義陣営と、【ソ連】を中心とする社会主義陣営の対立である。両国が【直接の戦争】をしなかったため冷戦とよばれる。' },
  { id: 'w20', s: 'wh', lv: 3, topic: 'キューバ危機', q: 'キューバ危機の経過と、その後の米ソ関係を述べよ。', a: '1962年、ソ連が【キューバ】に【ミサイル】基地を建設し、核戦争の危機が高まった。ソ連の撤去で回避され、その後米ソ間に【ホットライン】が設けられて【緊張緩和】が進んだ。' },
  { id: 'w21', s: 'wh', lv: 2, topic: 'アッバース朝', q: 'アッバース朝は、ウマイヤ朝とどのような点で異なるか。', a: 'ウマイヤ朝では【アラブ人】が特権をもったが、アッバース朝では【ムスリム】であれば民族に関係なく平等とされ、改宗した非アラブ人も【ジズヤ】（人頭税）を免除された。' },
  { id: 'w22', s: 'wh', lv: 2, topic: 'モンゴル帝国', q: 'モンゴル帝国の成立は、東西の交流にどのような影響を与えたか。', a: 'ユーラシアの広い範囲が一つの勢力のもとにまとまり、【駅伝制】（ジャムチ）が整備されて、陸路と【海路】の交易がさかんになった。【マルコ=ポーロ】などが東方を訪れた。' },
  { id: 'w23', s: 'wh', lv: 3, topic: '銀の流入', q: '16世紀以降、中国に大量の銀が流入した理由と影響を述べよ。', a: '【日本】や【アメリカ大陸】で産出された銀が、生糸や陶磁器の代価として中国に流れ込んだ。その結果、税を銀で一括して納める【一条鞭法】が実施された。' },
  { id: 'w24', s: 'wh', lv: 3, topic: 'ソ連解体', q: 'ソ連が解体に向かった過程を述べよ。', a: '【ゴルバチョフ】が【ペレストロイカ】と情報公開（【グラスノスチ】）を進めたが経済は改善せず、東欧では民主化が進んだ。1991年に各共和国が独立し、ソ連は解体した。' },
  // ===== 追加分(自動) =====
  {"id": "jhx1", "s": "jh", "lv": 1, "topic": "旧石器時代", "q": "岩宿遺跡の発見は、日本の歴史研究にとってどのような意義をもったか説明せよ。", "a": "【相沢忠洋】が群馬県の【岩宿】で【関東ローム層】から【打製石器】を発見し、それまで存在しないと考えられていた日本の旧石器時代の存在が明らかになった。"},
  {"id": "jhx2", "s": "jh", "lv": 1, "topic": "縄文文化の成立", "q": "縄文文化が成立した背景には、どのような自然環境の変化があったか説明せよ。", "a": "氷期が終わって気候が温暖化し、海面が上昇して【日本列島】が形成された。中小動物をとらえるために【弓矢】が使われ、木の実を煮るために【縄文土器】が作られるようになった。"},
  {"id": "jhx3", "s": "jh", "lv": 1, "topic": "貝塚", "q": "縄文時代の貝塚からは、当時のどのようなことがわかるか説明せよ。", "a": "貝塚は当時の【ごみ捨て場】で、貝殻や獣・魚の骨、土器などから人々の【食生活】や暮らしの様子がわかる。人骨が【埋葬】されている例もあり、モースが調査した【大森貝塚】が知られる。"},
  {"id": "jhx4", "s": "jh", "lv": 2, "topic": "縄文時代の信仰", "q": "縄文時代の人々の信仰や風習を、遺物・埋葬法にふれながら説明せよ。", "a": "自然物に霊威を認める【アニミズム】が広まり、女性をかたどった【土偶】で豊かな実りや出産を祈った。死者の手足を折り曲げて葬る【屈葬】や、成人の通過儀礼とされる【抜歯】も行われた。"},
  {"id": "jhx5", "s": "jh", "lv": 2, "topic": "三内丸山遺跡", "q": "三内丸山遺跡から明らかになった縄文時代の社会の特徴を説明せよ。", "a": "青森県の【三内丸山遺跡】は長期間営まれた大規模な集落跡で、大型掘立柱建物の跡や【クリ】の栽培を示す痕跡がある。新潟県産の【ヒスイ】なども出土し、遠隔地との【交易】があったことがわかる。"},
  {"id": "jhx6", "s": "jh", "lv": 1, "topic": "稲作と社会の変化", "q": "弥生時代に水稲耕作が広まると、社会はどのように変化したか説明せよ。", "a": "米を【高床倉庫】に蓄えられるようになると、【貧富の差】や身分の差が生まれた。土地や水をめぐる争いも起こり、各地に指導者が率いる小さな【クニ】が生まれた。"},
  {"id": "jhx7", "s": "jh", "lv": 1, "topic": "弥生時代の戦い", "q": "弥生時代に戦いがあったことは、どのような遺跡からわかるか説明せよ。", "a": "周囲に濠をめぐらせた【環濠集落】や、山頂など高い場所に営まれた【高地性集落】がみられる。佐賀県の【吉野ヶ里遺跡】では、首のない人骨や矢じりの刺さった人骨も見つかっている。"},
  {"id": "jhx8", "s": "jh", "lv": 2, "topic": "弥生時代の金属器", "q": "弥生時代に伝わった鉄器と青銅器は、それぞれ主にどのように用いられたか。", "a": "【鉄器】は農具や工具、武器など実用の道具として用いられた。一方、銅鐸・銅剣・銅矛などの【青銅器】は主に【祭器】として用いられた。稲の穂首刈りには【石包丁】が使われた。"},
  {"id": "jhx9", "s": "jh", "lv": 2, "topic": "漢・後漢と倭", "q": "中国の歴史書は、紀元前後の倭の国々と中国との関係をどのように記しているか。", "a": "『漢書』地理志は、倭が百余国に分かれ【楽浪郡】に定期的に使いを送ったと記す。『後漢書』東夷伝は、57年に【奴国】王が後漢に使いを送り、光武帝から【印綬】を授けられたと記している。"},
  {"id": "jhx10", "s": "jh", "lv": 1, "topic": "邪馬台国", "q": "卑弥呼はどのように国を治め、中国とどのような関係を結んだか説明せよ。", "a": "卑弥呼は【呪術】的な権威によって約30の国々を従えた。239年に【魏】に使いを送り、「【親魏倭王】」の称号と金印、銅鏡などを授けられた。"},
  {"id": "jhx11", "s": "jh", "lv": 2, "topic": "前方後円墳", "q": "前方後円墳が各地に広がったことは、どのようなことを示しているか説明せよ。", "a": "3世紀中ごろから近畿を中心に【前方後円墳】が築かれ、同じ形式の古墳が各地に広がった。これは地方の【首長】たちが【ヤマト政権】と政治的な連合関係を結んでいたことを示している。"},
  {"id": "jhx12", "s": "jh", "lv": 3, "topic": "古墳の副葬品", "q": "古墳時代の前期と中期で副葬品はどう変化したか。その変化が示す被葬者の性格の違いとともに説明せよ。", "a": "前期は【銅鏡】や玉などの呪術的・宗教的な品が中心で、被葬者は【司祭者】的な性格をもっていた。中期には【鉄製武器】や【馬具】が増え、朝鮮半島との交流を背景に、被葬者の【武人】的な性格が強まった。"},
  {"id": "jhx13", "s": "jh", "lv": 2, "topic": "倭の五王", "q": "5世紀に倭の五王が中国の南朝に使いを送ったのはなぜか説明せよ。", "a": "倭の五王は中国【南朝】に朝貢して皇帝の権威を借り、【朝鮮半島】南部での軍事的・外交的な立場を有利にするとともに、国内での地位を高めようとした。478年には倭王【武】が宋に上表文を送った。"},
  {"id": "jhx14", "s": "jh", "lv": 3, "topic": "ワカタケル大王", "q": "稲荷山古墳出土鉄剣と江田船山古墳出土大刀の銘文から、5世紀後半のヤマト政権について何がわかるか。", "a": "埼玉県の【稲荷山古墳】出土の鉄剣と熊本県の【江田船山古墳】出土の大刀には、ともに「【ワカタケル】大王」の名が刻まれている。5世紀後半には大王の勢力が【関東】から九州中部にまで及んでいたことがわかる。"},
  {"id": "jhx15", "s": "jh", "lv": 1, "topic": "渡来人", "q": "4〜6世紀に朝鮮半島などから来た渡来人は、日本にどのような技術や文化を伝えたか。", "a": "渡来人は硬質で灰色の【須恵器】の製作や、機織り・金属加工などの技術を伝えた。また【漢字】を用いて記録や外交文書の作成にあたり、6世紀には【儒教】も伝えられた。ヤマト政権は彼らを【品部】に組織した。"},
  {"id": "jhx16", "s": "jh", "lv": 2, "topic": "氏姓制度", "q": "ヤマト政権が豪族を支配するしくみであった氏姓制度を説明せよ。", "a": "ヤマト政権は豪族を血縁などで結ばれた【氏】に組織し、家柄や地位に応じて臣・連などの【姓】を与えた。豪族は私有民の【部曲】や私有地の田荘を支配しつつ、政権の職務を分担した。"},
  {"id": "jhx17", "s": "jh", "lv": 3, "topic": "磐井の乱", "q": "6世紀前半の磐井の乱の経過と、その後のヤマト政権による地方支配の変化を説明せよ。", "a": "527年、【新羅】と結んだ筑紫国造【磐井】が、朝鮮半島に向かう政権の軍を妨げて反乱を起こしたが、鎮圧された。その後ヤマト政権は地方豪族を【国造】に任じ、各地に直轄地の【屯倉】を設けて地方支配を強めた。"},
  {"id": "jhx18", "s": "jh", "lv": 2, "topic": "仏教の伝来", "q": "6世紀に仏教が伝わると、その受け入れをめぐってどのような対立が起きたか。", "a": "6世紀半ば、【百済】の聖明王から仏教が公式に伝えられた。受け入れをめぐって崇仏派の【蘇我氏】と排仏派の【物部氏】が対立し、587年に蘇我馬子が物部守屋を滅ぼした。"},
  {"id": "jhx19", "s": "jh", "lv": 1, "topic": "推古朝の政治", "q": "推古天皇の時代に、厩戸王（聖徳太子）らはどのような国づくりをめざしたか説明せよ。", "a": "厩戸王は【蘇我馬子】と協力し、家柄にとらわれず才能のある人物を登用するため【冠位十二階】を定めた。また【十七条憲法】で役人の心構えを示し、天皇を中心とする国家をめざした。"},
  {"id": "jhx20", "s": "jh", "lv": 2, "topic": "遣隋使", "q": "遣隋使派遣の目的と、607年の国書にみられる外交姿勢を説明せよ。", "a": "中国の進んだ制度や文化を学ぶため、607年に【小野妹子】を派遣した。国書では倭の王を「天子」と記して【対等】な立場を求める姿勢を示し、隋の皇帝【煬帝】の不興を買ったが、翌年には【留学生】や学問僧も派遣された。"},
  {"id": "jhx21", "s": "jh", "lv": 2, "topic": "飛鳥文化", "q": "7世紀前半に栄えた飛鳥文化の特徴を、代表的な寺院や仏像にふれて説明せよ。", "a": "日本で最初の【仏教】文化で、【法隆寺】などの寺院が建てられた。中国の【南北朝】の文化の影響を受け、鞍作鳥の釈迦三尊像など、【渡来人】の技術に支えられた国際色豊かな文化であった。"},
  {"id": "jhx22", "s": "jh", "lv": 1, "topic": "大化の改新", "q": "7世紀半ばの大化の改新は、どのような国家をめざして行われたか説明せよ。", "a": "645年、【中大兄皇子】と中臣鎌足は蘇我氏を倒した（乙巳の変）。翌年【改新の詔】を出し、豪族の私有地・私有民を廃止する【公地公民】の方針を示して、天皇中心の中央集権国家をめざした。"},
  {"id": "jhx23", "s": "jh", "lv": 2, "topic": "白村江の戦い", "q": "白村江の戦いの結果、日本はどのような防衛策をとったか説明せよ。", "a": "663年、【百済】復興を助けるため出兵したが、唐・新羅の連合軍に大敗した。その後、唐・新羅の侵攻に備えて北九州に【水城】や朝鮮式山城を築き、【防人】を置いて防衛を固め、都を近江大津宮に移した。"},
  {"id": "jhx24", "s": "jh", "lv": 2, "topic": "壬申の乱", "q": "672年の壬申の乱の結果、天皇の権力はどのように変化したか説明せよ。", "a": "672年、【大海人皇子】が大友皇子を破って即位し【天武天皇】となった。近江朝廷側の有力豪族が没落したため天皇の権力が強まり、【八色の姓】による豪族の再編や、律令・国史の編纂が進められた。"},
  {"id": "jhx25", "s": "jh", "lv": 2, "topic": "持統朝と藤原京", "q": "持統天皇の時代に進められた律令国家づくりを、法令・戸籍・都城にふれて説明せよ。", "a": "持統天皇は【飛鳥浄御原令】を施行し、690年にはそれにもとづいて【庚寅年籍】を作成した。694年には条坊制をもつ初めての本格的な都城である【藤原京】に遷都した。"},
  {"id": "jhx26", "s": "jh", "lv": 2, "topic": "白鳳文化", "q": "白鳳文化の特徴を、代表的な建築・美術・文学にふれて説明せよ。", "a": "天武・持統天皇の時代を中心とする文化で、【初唐】の文化の影響を受けた清新な文化である。【薬師寺】東塔などが建てられ、【高松塚古墳】の壁画が描かれた。【柿本人麻呂】らが和歌を詠んだ。"},
  {"id": "jhx27", "s": "jh", "lv": 1, "topic": "大宝律令", "q": "大宝律令によって整えられた中央と地方の統治のしくみを説明せよ。", "a": "701年に【大宝律令】が完成し、中央には神祇官と【太政官】の二官と八省が置かれた。地方は国・郡・里に分けられ、中央から派遣された【国司】と、地方豪族から任じられた【郡司】が治めた。"},
  {"id": "jhx28", "s": "jh", "lv": 2, "topic": "律令制下の農民負担", "q": "律令制のもとで、農民はどのような税や負担を負っていたか説明せよ。", "a": "口分田からの収穫の一部を稲で納める【租】、地方の特産物を納める【調】、労役の代わりに布などを納める【庸】を負担した。ほかに国司のもとで労働する【雑徭】や【兵役】もあり、農民の負担は重かった。"},
  {"id": "jhx29", "s": "jh", "lv": 2, "topic": "三世一身法", "q": "奈良時代に三世一身法が出された理由と、この法の限界を説明せよ。", "a": "人口の増加などで【口分田】が不足したため、723年に【三世一身法】を出し、開墾した土地の一定期間の私有を認めた。しかし期限が近づくと耕地が荒れたため、743年の【墾田永年私財法】につながった。"},
  {"id": "jhx30", "s": "jh", "lv": 3, "topic": "律令制の動揺", "q": "8世紀から9世紀にかけて、班田収授が行われにくくなったのはなぜか説明せよ。", "a": "重い負担から逃れるため農民の【浮浪】・逃亡が増え、男子を女子と偽るなど戸籍をごまかす【偽籍】も広がった。口分田の不足も重なって【戸籍】・計帳による把握がくずれ、班田の間隔が延びて、10世紀初めを最後にほとんど行われなくなった。"},
  {"id": "jhx31", "s": "jh", "lv": 1, "topic": "平城京", "q": "平城京はどのような都であったか、手本とした都や特徴にふれて説明せよ。", "a": "710年、唐の都【長安】にならって【平城京】に遷都した。道路で碁盤の目状に区画する【条坊制】がとられ、東西の市では【和同開珎】などの貨幣も使われた。"},
  {"id": "jhx32", "s": "jh", "lv": 1, "topic": "遣唐使", "q": "遣唐使はどのような目的で派遣され、どのような役割を果たしたか。", "a": "唐の進んだ【制度】や文化を取り入れるために派遣され、【留学生】や学問僧が同行した。【吉備真備】や玄昉は帰国後に政治で活躍した。894年、【菅原道真】の建議で派遣は停止された。"},
  {"id": "jhx33", "s": "jh", "lv": 1, "topic": "鎮護国家", "q": "聖武天皇が国分寺の建立や大仏の造立を命じたのはなぜか説明せよ。", "a": "疫病や藤原広嗣の乱などで社会不安が続いたため、【仏教】の力で国家を守ろうとする【鎮護国家】の思想にもとづいて、741年に【国分寺建立の詔】、743年に【大仏造立の詔】を出した。"},
  {"id": "jhx34", "s": "jh", "lv": 3, "topic": "奈良時代の政争", "q": "奈良時代には、政治の実権がどのように移り変わったか。藤原氏と他の勢力の動きを中心に説明せよ。", "a": "藤原不比等の死後、【長屋王】が政権を握ったが、不比等の4子に倒された。4子が疫病で死ぬと【橘諸兄】が政権を握り、その後【藤原仲麻呂】、さらに僧の【道鏡】が権力をふるうなど、政権の担い手は激しく交代した。"},
  {"id": "jhx35", "s": "jh", "lv": 2, "topic": "天平文化", "q": "天平文化の特徴を、国際性や代表的な文化財・書物にふれて説明せよ。", "a": "聖武天皇の時代を中心とする、仏教色の強い貴族文化である。盛唐の文化の影響を受けて【国際色】豊かで、【正倉院】の宝物には【シルクロード】を通じて伝わった品もある。『古事記』『日本書紀』や『【万葉集】』も編まれた。"},
  {"id": "jhx36", "s": "jh", "lv": 2, "topic": "古事記と日本書紀", "q": "奈良時代初めに成立した『古事記』と『日本書紀』の成立事情と、書き方の違いを説明せよ。", "a": "『【古事記】』は稗田阿礼が誦習したものを太安万侶が筆録して712年に成立した。『【日本書紀】』は舎人親王らが720年に完成させ、【漢文】の【編年体】で書かれ、【六国史】の最初となった。"},
  {"id": "jhx37", "s": "jh", "lv": 2, "topic": "行基", "q": "行基は朝廷からどのように扱われたか。その活動の変化とともに説明せよ。", "a": "行基は民衆に布教しながら用水や橋をつくる【社会事業】を行ったため、はじめは【僧尼令】に反するとして朝廷に弾圧された。のちに【大仏造立】に協力し、【大僧正】に任じられた。"},
  {"id": "jhx38", "s": "jh", "lv": 2, "topic": "東北経営", "q": "律令国家は東北地方の蝦夷に対してどのような政策をとったか説明せよ。", "a": "律令国家は陸奥国に【多賀城】を築いて支配を広げた。桓武天皇は【坂上田村麻呂】を征夷大将軍に任じ、蝦夷の族長【阿弖流為】を降伏させ、【胆沢城】を築いて支配の拠点を北へ進めた。"},
  {"id": "jhx39", "s": "jh", "lv": 2, "topic": "桓武天皇の政治", "q": "桓武天皇が平安京に遷都した理由と、行った政治改革を説明せよ。", "a": "寺院など【仏教】勢力の政治への介入を断ち、政治を立て直すため、784年に長岡京、794年に【平安京】へ遷都した。国司の交代を監督する【勘解由使】を置き、東北などを除いて軍団を廃止し【健児】を置いた。"},
  {"id": "jhx40", "s": "jh", "lv": 2, "topic": "令外官", "q": "平安時代初期に令外官が置かれたのはなぜか。代表的な官職をあげて説明せよ。", "a": "律令の規定だけでは現実の政治に対応できなくなったため、律令にない【令外官】が置かれた。嵯峨天皇は機密を扱う【蔵人頭】や、京の治安を担う【検非違使】を置いた。また法令を整理した【格式】も編纂された。"},
  {"id": "jhx41", "s": "jh", "lv": 1, "topic": "天台宗と真言宗", "q": "平安時代初期に最澄と空海が広めた新しい仏教の特徴を説明せよ。", "a": "最澄は【比叡山】延暦寺を開いて【天台宗】を、空海は高野山金剛峯寺を開いて【真言宗】を広めた。両宗は加持祈祷で災いを除き現世の利益を願う【密教】を取り入れ、貴族の信仰を集めた。"},
  {"id": "jhx42", "s": "jh", "lv": 2, "topic": "弘仁・貞観文化", "q": "平安時代初期の弘仁・貞観文化の特徴を、文学・仏教美術・書道にふれて説明せよ。", "a": "宮廷では【漢詩文】が重んじられ、勅撰漢詩集が編まれた。仏教では【密教】が盛んになり、【曼荼羅】や一木造の神秘的な仏像が作られた。書道では嵯峨天皇・空海・橘逸勢の【三筆】が活躍した。"},
  {"id": "jhx43", "s": "jh", "lv": 2, "topic": "藤原北家の他氏排斥", "q": "藤原北家は、9〜10世紀にどのようにして他の貴族を政界から退けたか説明せよ。", "a": "藤原良房は【承和の変】で伴健岑・橘逸勢を退け、【応天門の変】で伴善男を失脚させた。藤原時平は【菅原道真】を大宰府に左遷させ、969年の【安和の変】で源高明が退けられて北家の地位が確立した。"},
  {"id": "jhx44", "s": "jh", "lv": 3, "topic": "摂関期の政治運営", "q": "摂関政治の時代、政治はどのように運営され、なぜ中・下級貴族は摂関家に近づいたのか説明せよ。", "a": "摂関政治の時代も政治は【太政官】で行われ、重要事項は公卿の会議である【陣定】で審議された。摂政・関白は官吏の【人事権】を握っていたため、中・下級貴族は摂関家に近づき、収入の多い【受領】の地位を求めた。"},
  {"id": "jhx45", "s": "jh", "lv": 1, "topic": "国風文化", "q": "遣唐使の停止前後から栄えた国風文化の特徴を、文字・文学・住宅にふれて説明せよ。", "a": "唐の文化を消化し、日本の風土や生活に合った文化が生まれた。【かな文字】が発達して紫式部の『【源氏物語】』や清少納言の『枕草子』などの女流文学が生まれ、貴族の住宅には【寝殿造】が用いられた。"},
  {"id": "jhx46", "s": "jh", "lv": 2, "topic": "浄土教", "q": "平安時代中期に浄土教が広まった理由と、その広がりを示す例を説明せよ。", "a": "社会不安と、仏の教えが衰えるという【末法思想】の広がりから、【阿弥陀仏】を信じて極楽浄土への往生を願う浄土教が広まった。【空也】が都で念仏を説き、源信は『往生要集』を著し、藤原頼通は【平等院鳳凰堂】を建てた。"},
  {"id": "jhx47", "s": "jh", "lv": 3, "topic": "受領と地方支配の変化", "q": "10世紀に国司による地方支配はどのように変化したか。課税のしくみの変化とあわせて説明せよ。", "a": "政府は国司に一定額の税の納入を請け負わせ、国内の支配を任せた。任国に赴く最上席の国司は【受領】とよばれ、課税対象を人から土地へ改めた。田地を【名】に編成し、有力農民の【田堵】に耕作と納税を請け負わせた。"},
  {"id": "jhx48", "s": "jh", "lv": 2, "topic": "寄進地系荘園", "q": "11世紀ごろに広がった寄進地系荘園は、どのようにして生まれたか説明せよ。", "a": "開発領主は国司の干渉や税の負担を逃れるため、所領を中央の有力な貴族や寺社に【寄進】した。寄進を受けた者は【領家】、さらに上級の者は【本家】となり、荘園は【不輸の権】や不入の権を得て独立性を強めた。"},
  {"id": "jhx49", "s": "jh", "lv": 1, "topic": "承平・天慶の乱", "q": "10世紀前半の承平・天慶の乱は、武士の成長にとってどのような意味をもったか。", "a": "関東で【平将門】が、瀬戸内海で【藤原純友】が反乱を起こした。朝廷は地方の【武士】の力を借りてこれらを鎮圧したため、武士の実力が明らかになり、その地位が高まった。"},
  {"id": "jhx50", "s": "jh", "lv": 2, "topic": "源氏の東国進出", "q": "11世紀の東北地方の争乱は、源氏の勢力拡大とどのように結びついたか説明せよ。", "a": "東北の争乱である【前九年合戦】と【後三年合戦】を源頼義・【源義家】らが鎮めたことで、源氏は【東国】の武士との主従関係を強めた。その後、奥州では【奥州藤原氏】が平泉を拠点に栄えた。"},
  {"id": "jhx51", "s": "jh", "lv": 2, "topic": "延久の荘園整理令", "q": "後三条天皇が出した延久の荘園整理令の内容と、その意義を説明せよ。", "a": "1069年、【後三条天皇】は【記録荘園券契所】を置き、証拠書類の不備な荘園や新しい荘園を停止させた。【摂関家】の荘園も例外とせず、摂関家と外戚関係のない天皇が政治の主導権を取り戻した。"},
  {"id": "jhx52", "s": "jh", "lv": 3, "topic": "院政の権力基盤", "q": "院政期の上皇の権力は、どのようなものに支えられていたか。直面した問題とあわせて説明せよ。", "a": "上皇は【院宣】や院庁下文で政治を動かし、【北面の武士】を置いて武力を備えた。上皇のもとには多くの【荘園】が寄進され、知行国の制度も経済基盤となった。一方、大寺院が僧兵を使って起こす【強訴】に悩まされた。"},
  {"id": "jhx53", "s": "jh", "lv": 2, "topic": "院政期の文化", "q": "院政期の文化の特徴を、地方への広がりや庶民の文化にふれて説明せよ。", "a": "浄土教が地方にも広まり、奥州藤原氏の【中尊寺金色堂】などが建てられた。後白河上皇は庶民の流行歌である【今様】を『梁塵秘抄』にまとめ、『鳥獣戯画』などの【絵巻物】も作られた。"},
  {"id": "jhx54", "s": "jh", "lv": 1, "topic": "平氏政権", "q": "平清盛は、どのようにして政治の実権を握り、どのような政策を行ったか説明せよ。", "a": "清盛は【保元の乱】・平治の乱に勝利し、1167年に武士として初めて【太政大臣】となった。娘を天皇の后として外戚となり、大輪田泊を修築して【日宋貿易】を進め、大きな利益をあげた。"},
  {"id": "jhx55", "s": "jh", "lv": 3, "topic": "平氏政権の性格", "q": "平氏政権がもっていた貴族的な性格と武家政権としての性格を、滅亡の理由とあわせて説明せよ。", "a": "平氏は一門で高位高官を独占し、【外戚】として権力を握るなど摂関家に似た【貴族的】な性格をもった。一方、各地の武士を家人とし【地頭】に任じた点では武家政権の性格もあった。院や旧勢力、地方武士の反発を招き、【治承・寿永の乱】で滅んだ。"},
  {"id": "jhx56", "s": "jh", "lv": 1, "topic": "守護と地頭", "q": "源頼朝が全国に置いた守護と地頭は、それぞれどのような役割を担ったか説明せよ。", "a": "1185年、頼朝は朝廷に認めさせ、国ごとに【守護】を置いて軍事・警察を担当させ、荘園や公領ごとに【地頭】を置いて年貢の徴収や土地の管理にあたらせた。これにより頼朝の支配が【全国】に及んだ。"},
  {"id": "jhx57", "s": "jh", "lv": 2, "topic": "執権政治", "q": "北条氏による執権政治は、どのように確立し、どのような特徴をもったか。", "a": "頼朝の死後、北条時政が【執権】となり、2代義時は【承久の乱】に勝利して地位を固めた。3代泰時は有力御家人による合議制をとって【評定衆】を置き、【御成敗式目】を定めた。"},
  {"id": "jhx58", "s": "jh", "lv": 1, "topic": "承久の乱", "q": "承久の乱の結果、鎌倉幕府の支配はどのように変化したか説明せよ。", "a": "1221年、【後鳥羽上皇】が倒幕の兵をあげたが敗れ、隠岐に流された。幕府は京都に【六波羅探題】を置いて朝廷を監視し、上皇方の所領に【新補地頭】を置いて、支配を西国にまで広げた。"},
  {"id": "jhx59", "s": "jh", "lv": 2, "topic": "御成敗式目", "q": "北条泰時が御成敗式目を定めた目的と、その基準となったものを説明せよ。", "a": "1232年、泰時は頼朝以来の【先例】と武家社会の【道理】にもとづき、【御家人】の間や御家人と荘園領主の間の争いを公平に裁く基準として定めた。最初の【武家法】で、朝廷の法を否定するものではなかった。"},
  {"id": "jhx60", "s": "jh", "lv": 3, "topic": "地頭の荘園侵略", "q": "鎌倉時代に地頭と荘園領主の対立はどのように解決がはかられ、その結果どうなったか説明せよ。", "a": "地頭が年貢を横領するなど荘園領主と対立すると、領主は地頭に一定額の年貢納入を請け負わせる【地頭請】や、土地を領主と地頭で分け合う【下地中分】で解決をはかった。その結果、地頭の【現地支配】が強まり、【荘園】制は変質していった。"},
  {"id": "jhx61", "s": "jh", "lv": 1, "topic": "鎌倉時代の産業", "q": "鎌倉時代には、農業や商業にどのような発達がみられたか説明せよ。", "a": "畿内や西日本で麦を裏作とする【二毛作】が広まり、刈敷や草木灰が肥料に使われた。寺社の門前や交通の要地では【定期市】が開かれ、【宋銭】が流通し、遠隔地の取引には【為替】が用いられた。"},
  {"id": "jhx62", "s": "jh", "lv": 2, "topic": "惣領制", "q": "鎌倉時代の武士の一族結合である惣領制と、その相続方法の変化を説明せよ。", "a": "武士は一族の長である【惣領】が庶子を率いて戦い、幕府への奉公を果たした。所領は【分割相続】されたため細分化が進み、御家人は困窮した。そのため鎌倉後期には惣領が所領を受け継ぐ【単独相続】へと移っていった。"},
  {"id": "jhx63", "s": "jh", "lv": 3, "topic": "得宗専制", "q": "蒙古襲来後の鎌倉幕府でみられた得宗専制とはどのような政治か。成立の経緯とあわせて説明せよ。", "a": "蒙古襲来後、北条氏の嫡流である【得宗】の権力が強まり、得宗の家臣である【御内人】が幕政に大きな影響力をもった。1285年の【霜月騒動】で有力御家人の安達泰盛が滅ぼされると得宗専制が確立し、【御家人】の不満が高まった。"},
  {"id": "jhx64", "s": "jh", "lv": 3, "topic": "鎌倉幕府の滅亡", "q": "鎌倉幕府が滅亡に至った背景を、御家人の状況や社会の変化にふれて説明せよ。", "a": "分割相続や【貨幣経済】の浸透で御家人が困窮する一方、【得宗専制】への反発が強まった。畿内では荘園領主や幕府に反抗する【悪党】が現れた。【後醍醐天皇】の倒幕計画に足利高氏や新田義貞らが応じ、1333年に幕府は滅亡した。"},
  {"id": "jhx65", "s": "jh", "lv": 2, "topic": "鎌倉文化の美術", "q": "鎌倉時代の彫刻・建築には、どのような特徴がみられるか説明せよ。", "a": "武士の気風を反映した力強く写実的な作品が生まれ、東大寺南大門の【金剛力士像】は【運慶】・快慶らが制作した。東大寺の再建では宋の様式を取り入れた【大仏様】が用いられ、禅宗寺院には【禅宗様】が用いられた。"},
  {"id": "jhx66", "s": "jh", "lv": 2, "topic": "鎌倉時代の文学", "q": "鎌倉時代に生まれた文学の特徴を、軍記物語や随筆にふれて説明せよ。", "a": "平氏の興亡を描いた軍記物語『【平家物語】』は、【琵琶法師】によって語られ、文字を読めない人々にも広まった。また【鴨長明】の『方丈記』や兼好法師の『【徒然草】』など、無常観を背景とする随筆も生まれた。"},
  {"id": "jhx67", "s": "jh", "lv": 1, "topic": "建武の新政", "q": "後醍醐天皇の建武の新政が、短期間で失敗したのはなぜか説明せよ。", "a": "【後醍醐天皇】は天皇中心の政治をめざしたが、公家を重んじる政策や、【恩賞】の不公平に【武士】が不満を強めた。武家政治の再興をめざす【足利尊氏】が離反し、新政は約2年半で崩れた。"},
  {"id": "jhx68", "s": "jh", "lv": 3, "topic": "南北朝の動乱", "q": "南北朝の動乱が約60年もの長期に及んだ理由を、武士社会の変化にふれて説明せよ。", "a": "【惣領制】がくずれて武士団の内部で分裂が起こり、一方が北朝につけば他方が南朝につくなど対立が複雑化した。幕府内部でも足利尊氏と直義が争う【観応の擾乱】が起きた。地縁的な結合を強めた武士は【守護】に従い、守護が権限を拡大した。"},
  {"id": "jhx69", "s": "jh", "lv": 2, "topic": "守護大名", "q": "南北朝の動乱の中で、守護はどのようにして守護大名へと成長したか説明せよ。", "a": "幕府は守護に、荘園・公領の年貢の半分を兵粮米として徴収できる【半済令】や、【刈田狼藉】の取り締まりなどの権限を与えた。守護は国内の武士を家臣化し、荘園の年貢納入を請け負う【守護請】も行って、【守護大名】へと成長した。"},
  {"id": "jhx70", "s": "jh", "lv": 2, "topic": "室町幕府の機構", "q": "室町幕府の中央と地方の主な機構と、それぞれの長官に任じられた人々を説明せよ。", "a": "将軍を補佐する【管領】には細川・斯波・畠山の三氏が交代で任じられ、侍所の長官には四職が任じられた。地方には関東を治める【鎌倉府】が置かれ、長官の【鎌倉公方】は足利基氏の子孫が世襲した。"},
  {"id": "jhx71", "s": "jh", "lv": 2, "topic": "足利義満の権力確立", "q": "足利義満はどのようにして室町幕府の権力を確立したか説明せよ。", "a": "義満は1392年に【南北朝の合一】を実現し、【明徳の乱】で山名氏清を、【応永の乱】で大内義弘を討って有力守護の勢力を抑えた。また【太政大臣】となって公家社会でも頂点に立った。"},
  {"id": "jhx72", "s": "jh", "lv": 3, "topic": "室町幕府の財政", "q": "室町幕府の財政はどのような収入によって支えられていたか、その特徴とともに説明せよ。", "a": "直轄領である【御料所】からの収入が少なかったため、高利貸しの【土倉】・酒屋に課す土倉役・酒屋役、交通の要地に設けた【関銭】・津料、日明貿易の利益などに頼った。守護を通じて【段銭】・棟別銭も徴収するなど、商業や流通への課税に依存した。"},
  {"id": "jhx73", "s": "jh", "lv": 3, "topic": "足利義教と嘉吉の乱", "q": "6代将軍足利義教の政治と嘉吉の乱は、室町幕府にどのような影響を与えたか。", "a": "【足利義教】は将軍権力の強化をめざし、【永享の乱】で鎌倉公方足利持氏を滅ぼすなど専制的な政治を行った。しかし守護の反発を招き、1441年に播磨守護【赤松満祐】に殺された（【嘉吉の乱】）。これ以後、将軍の権威は大きく衰えた。"},
  {"id": "jhx74", "s": "jh", "lv": 1, "topic": "惣村", "q": "室町時代の農村で成立した惣村とは、どのような村であったか説明せよ。", "a": "農民が自治的な村である【惣】をつくり、【寄合】で村のおきてである惣掟を定め、入会地や用水を共同で管理した。団結した農民は年貢の減免などを求めて【一揆】を結ぶこともあった。"},
  {"id": "jhx75", "s": "jh", "lv": 2, "topic": "正長の土一揆", "q": "1428年に起きた正長の土一揆の経過と、その歴史的な意味を説明せよ。", "a": "近江の【馬借】の蜂起をきっかけに、京都周辺の農民が【徳政】を要求して酒屋・【土倉】などの高利貸しを襲った。幕府は徳政令を出さなかったが、各地で実力による【私徳政】が行われ、民衆の力が示された。"},
  {"id": "jhx76", "s": "jh", "lv": 2, "topic": "山城の国一揆と加賀の一向一揆", "q": "15世紀後半の山城の国一揆と加賀の一向一揆は、それぞれどのような一揆か説明せよ。", "a": "1485年、南山城の国人と農民は争う【畠山氏】の軍を国外に退去させ、8年間自治を行った。1488年には浄土真宗の門徒らによる加賀の【一向一揆】が守護【富樫政親】を倒し、約100年間にわたって自治を行った。"},
  {"id": "jhx77", "s": "jh", "lv": 2, "topic": "室町時代の産業", "q": "室町時代の農業はどのように発達したか。商品作物や市の発達とあわせて説明せよ。", "a": "畿内では【三毛作】も行われ、人糞尿の【下肥】が肥料として使われた。灯油の原料となる【荏胡麻】や茶などの商品作物も栽培された。地方の市は月に6回開かれる【六斎市】が一般的になった。"},
  {"id": "jhx78", "s": "jh", "lv": 2, "topic": "室町時代の流通", "q": "室町時代の商工業者や流通、貨幣の使用にはどのような特徴がみられたか。", "a": "陸上輸送は【馬借】・車借、港での保管・輸送は問丸が担った。商工業者は【座】を結んで公家や寺社の保護を受け、独占的な営業権を得た。明銭の【永楽通宝】なども使われたが、粗悪な銭を嫌う【撰銭】が行われ、取引の妨げとなった。"},
  {"id": "jhx79", "s": "jh", "lv": 2, "topic": "北山文化", "q": "足利義満の時代の北山文化の特徴を、建築や芸能にふれて説明せよ。", "a": "伝統的な【公家】文化と新しい武家文化が融合し、【禅宗】の影響も受けた文化である。義満が京都の北山に建てた【金閣】がその象徴で、【観阿弥】・世阿弥父子が能を大成した。"},
  {"id": "jhx80", "s": "jh", "lv": 1, "topic": "東山文化", "q": "足利義政の時代の東山文化の特徴を、建築や絵画にふれて説明せよ。", "a": "禅の精神にもとづく簡素で深みのある美が重んじられた。慈照寺の東求堂同仁斎には、現代の和風住宅のもととなる【書院造】が用いられた。【雪舟】は【水墨画】を大成し、石や砂で自然を表す【枯山水】の庭園もつくられた。"},
  {"id": "jhx81", "s": "jh", "lv": 3, "topic": "文化の地方・庶民への広がり", "q": "室町時代後期に文化が地方や庶民に広がったのはなぜか。具体例をあげて説明せよ。", "a": "応仁の乱で京都が荒廃すると、多くの【公家】や禅僧が地方の大名を頼って下り、文化が【地方】に広まった。宗祇らが各地で【連歌】を広め、御伽草子や狂言など庶民も楽しめる文芸が生まれ、都市の町衆や村の農民も文化の担い手となった。"},
  {"id": "jhx82", "s": "jh", "lv": 2, "topic": "日朝貿易", "q": "室町時代の日朝貿易はどのように行われ、どのように衰えたか説明せよ。", "a": "朝鮮は【倭寇】の禁止を求めて日本と通交し、【対馬】の【宗氏】を通じて貿易を統制した。日本は朝鮮から【木綿】などを輸入した。1510年に朝鮮の港に住む日本人が暴動を起こした【三浦の乱】以後、貿易は衰えた。"},
  {"id": "whx1", "s": "wh", "lv": 1, "topic": "ハンムラビ法典", "q": "バビロン第1王朝のハンムラビ王が制定した法典の特徴を述べよ。", "a": "メソポタミアを統一した【ハンムラビ王】が制定した。「目には目を、歯には歯を」の【同害復讐】を原則としながら、被害者や加害者の【身分】によって刑罰に差をつけた。"},
  {"id": "whx2", "s": "wh", "lv": 1, "topic": "古代エジプトの王権", "q": "古代エジプトのファラオは、どのような存在として国を支配したか。", "a": "ファラオは太陽神【ラー】の子とされ、生ける神として【神権政治】をおこなった。【ナイル川】の治水と農業を管理する強大な権力をもち、古王国時代には巨大な【ピラミッド】を建設させた。"},
  {"id": "whx3", "s": "wh", "lv": 2, "topic": "アケメネス朝の統治", "q": "アケメネス朝ペルシアは、多様な民族が住む広大な領土をどのように統治したか。", "a": "全国を州に分けて知事【サトラップ】をおき、「王の目」「王の耳」とよばれる監察官に監視させた。幹線道路【王の道】と駅伝制で交通を整え、服属民の宗教や慣習には【寛容】な政策をとった。"},
  {"id": "whx4", "s": "wh", "lv": 2, "topic": "フェニキア人", "q": "フェニキア人の活動は、地中海世界にどのような影響を与えたか。", "a": "【シドン】や【ティルス】を拠点に地中海交易で活躍し、北アフリカに【カルタゴ】などの植民市を建設した。彼らの表音文字はギリシア人に伝わり、【アルファベット】の起源となった。"},
  {"id": "whx5", "s": "wh", "lv": 1, "topic": "ユダヤ教", "q": "ヘブライ人のユダヤ教は、どのような特徴をもつ宗教として成立したか。", "a": "【バビロン捕囚】などの苦難のなかで、唯一神【ヤハウェ】を信じる【一神教】として確立した。自分たちだけが神に救われるとする【選民思想】や、救世主（メシア）を待望する信仰をもった。"},
  {"id": "whx6", "s": "wh", "lv": 1, "topic": "ポリス", "q": "古代ギリシアのポリスとはどのような共同体か、その特徴を述べよ。", "a": "有力者を中心に人々が【集住】して成立した都市国家で、城山の【アクロポリス】と広場の【アゴラ】を中心とした。ポリスは互いに独立していたが、同一民族として【ヘレネス】という意識をもった。"},
  {"id": "whx7", "s": "wh", "lv": 1, "topic": "アテネ民主政", "q": "ペルシア戦争後、ペリクレス時代のアテネで完成した民主政の特徴を述べよ。", "a": "【ペリクレス】の時代に完成し、成年男子市民が【民会】で国政を決める【直接民主政】がおこなわれた。一方で、女性・【奴隷】・在留外人には参政権がなかった。"},
  {"id": "whx8", "s": "wh", "lv": 2, "topic": "民主政の発展", "q": "アテネで平民の発言力が高まり、民主政が発展した背景を述べよ。", "a": "交易で富を得た平民が武具を自弁して【重装歩兵】となり、国防の主力となって発言力を強めた。【ソロンの改革】や【クレイステネスの改革】を経て、【サラミスの海戦】では無産市民も軍船の漕ぎ手として活躍し、民主政が完成に向かった。"},
  {"id": "whx9", "s": "wh", "lv": 2, "topic": "ペロポネソス戦争", "q": "ペロポネソス戦争は、ギリシア世界にどのような結果をもたらしたか。", "a": "【デロス同盟】を率いるアテネと、【ペロポネソス同盟】を率いるスパルタが争い、スパルタが勝利した。その後もポリス間の抗争が続いてポリス社会は衰え、北方の【マケドニア】に支配された。"},
  {"id": "whx10", "s": "wh", "lv": 2, "topic": "ヘレニズム文化", "q": "アレクサンドロス大王の遠征後に生まれたヘレニズム文化の特徴を述べよ。", "a": "【アレクサンドロス大王】の東方遠征後、ギリシア文化がオリエントに広まって生まれた文化。ポリスの枠をこえた【世界市民主義】（コスモポリタニズム）が特徴で、エジプトの【アレクサンドリア】が学術の中心となった。"},
  {"id": "whx11", "s": "wh", "lv": 1, "topic": "スパルタ", "q": "ギリシアのポリスであるスパルタは、どのような体制で国家を維持したか。", "a": "少数の市民が多数の隷属農民【ヘイロータイ】を支配したため、反乱に備えて市民に厳しい軍事訓練を課す【軍国主義】をとった。この体制は【リュクルゴスの制】とよばれ、他国との交流を制限する【鎖国】政策をとった。"},
  {"id": "whx12", "s": "wh", "lv": 1, "topic": "ローマの身分闘争", "q": "共和政ローマで、平民が政治的権利を拡大していった過程を述べよ。", "a": "重装歩兵として国防を担った平民は貴族に対抗し、【護民官】と平民会が設けられた。【十二表法】で慣習法が成文化され、前287年の【ホルテンシウス法】で平民会の議決が国法とされ、平民と貴族は法的に平等となった。"},
  {"id": "whx13", "s": "wh", "lv": 2, "topic": "共和政の動揺", "q": "ポエニ戦争後のローマで、共和政が動揺した理由を社会の変化から述べよ。", "a": "属州から安い穀物が流入し、長期の従軍で疲弊した【中小農民】が没落した。富裕層は奴隷を使う大土地所有【ラティフンディア】を広げた。農民の再建をめざす【グラックス兄弟】の改革は失敗し、【内乱の一世紀】に入った。"},
  {"id": "whx14", "s": "wh", "lv": 1, "topic": "キリスト教の公認", "q": "ローマ帝国でキリスト教が迫害から公認、国教化へと至った過程を述べよ。", "a": "当初は皇帝崇拝を拒んだため迫害されたが、信者は増え続けた。【コンスタンティヌス帝】が313年の【ミラノ勅令】でキリスト教を公認し、392年には【テオドシウス帝】が国教とし、他の宗教を禁止した。"},
  {"id": "whx15", "s": "wh", "lv": 2, "topic": "3世紀の危機", "q": "3世紀のローマ帝国はどのような危機にみまわれ、どのように再建されたか。", "a": "各地の軍団が皇帝を擁立する【軍人皇帝】時代となり、異民族の侵入も重なって帝国は混乱した。【ディオクレティアヌス帝】は皇帝を神格化する【専制君主政】（ドミナトゥス）を始め、帝国を四分統治して秩序を回復した。"},
  {"id": "whx16", "s": "wh", "lv": 2, "topic": "コロナトゥス", "q": "ローマ帝政後期に広がったコロナトゥスとは、どのような生産体制か。", "a": "征服戦争が終わって【奴隷】の供給が減ると、【ラティフンディア】にかわり、没落農民などを小作人の【コロヌス】として使う体制が広がった。コロヌスはやがて土地に縛られ、中世の【農奴】の先駆けとなった。"},
  {"id": "whx17", "s": "wh", "lv": 3, "topic": "ギリシアとローマの市民権", "q": "古代アテネとローマの市民権のあり方を比較し、それが国家の発展に与えた影響を論ぜよ。", "a": "アテネは市民権を【血統】によって厳しく限定し、閉鎖的だった。ローマは征服した都市を【分割統治】しつつ段階的に市民権を与え、【同盟市戦争】を経てイタリア全域に拡大し、212年には【カラカラ帝】が帝国の全自由民に市民権を与え、広大な帝国の統合を支えた。"},
  {"id": "whx18", "s": "wh", "lv": 3, "topic": "ローマ法", "q": "ローマ法はどのように発展し、それが後世にどのような影響を与えたかを述べよ。", "a": "当初はローマ市民にのみ適用される【市民法】だったが、帝国の拡大にともない、あらゆる民族に適用される【万民法】へと発展した。6世紀に【ユスティニアヌス帝】が【ローマ法大全】に集大成し、近代ヨーロッパの法体系の基礎となった。"},
  {"id": "whx19", "s": "wh", "lv": 1, "topic": "ゲルマン人の大移動", "q": "ゲルマン人の大移動はどのように始まり、どのような結果をもたらしたか。", "a": "4世紀後半、アジア系の【フン人】に圧迫された【西ゴート人】がローマ帝国領内に移動したことで始まった。この混乱のなかで【西ローマ帝国】は476年に滅亡し、各地にゲルマン人の国家が建てられた。"},
  {"id": "whx20", "s": "wh", "lv": 3, "topic": "アッシリアとアケメネス朝", "q": "オリエントを統一したアッシリアとアケメネス朝の支配のあり方の違いを論ぜよ。", "a": "アッシリアは鉄製武器と戦車で征服し、服属民の【強制移住】や重税をともなう【武断的な支配】をおこなったため、反乱を招いて短期間で崩壊した。アケメネス朝は【サトラップ】による州制度で統治しつつ、服属民の宗教や慣習に【寛容】で、約200年にわたり広大な領域を維持した。"},
  {"id": "whx21", "s": "wh", "lv": 1, "topic": "インダス文明", "q": "インダス川流域に栄えたインダス文明の特徴を、都市と文字に触れて述べよ。", "a": "前2600年ごろからインダス川流域に栄えた青銅器文明で、【モエンジョ=ダーロ】や【ハラッパー】などの計画的な都市を築いた。都市には排水設備や沐浴場が整えられていた。印章に刻まれた【インダス文字】は未解読である。"},
  {"id": "whx22", "s": "wh", "lv": 1, "topic": "ヴァルナ制", "q": "アーリヤ人の社会で形成されたヴァルナ制とは、どのような身分制度か。", "a": "司祭の【バラモン】を最上位に、武士の【クシャトリヤ】、庶民のヴァイシャ、隷属民の【シュードラ】の4つの身分に分ける制度。のちに世襲の職業集団【ジャーティ】と結びつき、【カースト制度】が形成された。"},
  {"id": "whx23", "s": "wh", "lv": 1, "topic": "仏教の成立", "q": "古代インドで、仏教はどのような背景のもとで成立し、何を説いたか。", "a": "前6世紀ごろ、バラモンの権威や祭式主義への批判が高まるなかで、【ガウタマ=シッダールタ】が開いた。ヴァルナによる差別を否定し、【八正道】の実践による【解脱】を説き、【クシャトリヤ】や商人から支持された。"},
  {"id": "whx24", "s": "wh", "lv": 2, "topic": "アショーカ王", "q": "マウリヤ朝のアショーカ王は、どのような理念にもとづいて統治をおこなったか。", "a": "【カリンガ】征服の悲惨さを反省し、倫理である【ダルマ】（法）による政治を理想とした。【仏教】を保護して【仏典結集】をおこない、各地に詔勅を刻んだ石柱碑や磨崖碑を建てた。"},
  {"id": "whx25", "s": "wh", "lv": 2, "topic": "ガンダーラ美術", "q": "クシャーナ朝の時代に栄えた仏教と仏教美術の特徴について述べよ。", "a": "【カニシカ王】の保護のもと、菩薩信仰により広く人々の救済をめざす【大乗仏教】が広まった。ヘレニズム文化の影響を受けた【ガンダーラ美術】で仏像が作られ、仏教は中央アジアを経て東アジアへ伝わった。"},
  {"id": "whx26", "s": "wh", "lv": 2, "topic": "グプタ朝の文化", "q": "グプタ朝の時代に、インド古典文化が成立したことについて述べよ。", "a": "バラモン教に民間信仰が融合した【ヒンドゥー教】が定着し、【マヌ法典】が完成した。【サンスクリット語】が公用語化され、カーリダーサの『シャクンタラー』などの文学が栄えた。数学では【ゼロの概念】が生まれた。"},
  {"id": "whx27", "s": "wh", "lv": 1, "topic": "周の封建制", "q": "周王朝がおこなった封建制とは、どのような仕組みの統治制度か。", "a": "周王が一族や功臣に【封土】を与えて【諸侯】とし、諸侯は王に貢納と軍役の義務を負った。この主従関係は、父系の血縁集団の規範である【宗法】によって支えられた。"},
  {"id": "whx28", "s": "wh", "lv": 1, "topic": "諸子百家", "q": "春秋・戦国時代に諸子百家が登場した背景と、その主な思想を述べよ。", "a": "【鉄製農具】の普及で生産力が高まり、諸侯が富国強兵のため有能な人材を求めた。こうしたなかで、仁と礼を説く【儒家】、法による統治を説く【法家】、無為自然を説く【道家】など多様な思想家が活躍した。"},
  {"id": "whx29", "s": "wh", "lv": 1, "topic": "始皇帝の統一政策", "q": "中国を統一した秦の始皇帝がおこなった、主な統一政策を述べよ。", "a": "全国に【郡県制】をしいて中央集権化を進め、【貨幣】・度量衡・文字を統一した。【焚書・坑儒】で思想統制をおこない、北方の匈奴に備えて【万里の長城】を修築した。"},
  {"id": "whx30", "s": "wh", "lv": 2, "topic": "郡国制", "q": "前漢の高祖（劉邦）が採用した郡国制とは、どのような統治制度か。", "a": "秦の急激な中央集権化の失敗をふまえ、都の周辺には【郡県制】をしき、地方には一族や功臣を王とする【封建制】を併用した。景帝が【呉楚七国の乱】を鎮圧したことで、実質的に中央集権化が進んだ。"},
  {"id": "whx31", "s": "wh", "lv": 2, "topic": "武帝の政策", "q": "前漢の武帝の対外政策と、それにともなう財政政策について述べよ。", "a": "【匈奴】を攻撃して西域へ進出し、朝鮮やベトナム北部にも郡をおいた。遠征で財政が悪化したため、【塩・鉄・酒の専売】や、物価を調整する【均輸・平準】をおこなった。"},
  {"id": "whx32", "s": "wh", "lv": 2, "topic": "儒学の官学化", "q": "漢代に儒学が国家の学問となった経緯と、それが政治や社会に与えた影響を述べよ。", "a": "武帝は【董仲舒】の献策で【五経博士】をおき、儒学を官学とした。官吏登用法の【郷挙里選】により地方の【豪族】が官界に進出した。後漢では経典の字句を解釈する【訓詁学】が発達した。"},
  {"id": "whx33", "s": "wh", "lv": 3, "topic": "漢とローマの交流", "q": "前2世紀から後2世紀のユーラシア東西交流について、漢とローマの関係に触れて述べよ。", "a": "武帝が【張騫】を大月氏に派遣して西域の事情が知られ、オアシス都市を結ぶ【シルク=ロード】が開けた。後漢の【班超】は西域を経営し、部下を大秦（ローマ）に派遣した。166年には【大秦王安敦】の使者を称する者が海路で日南郡に至った。"},
  {"id": "whx34", "s": "wh", "lv": 3, "topic": "九品中正", "q": "魏で始まった官吏登用法の九品中正が、魏晋南北朝時代の社会に与えた影響を論ぜよ。", "a": "【九品中正】は地方の中正官が人材を九等に評価して推薦する制度だが、実際には有力【豪族】の子弟が高く評価され、「上品に寒門なく、下品に勢族なし」といわれた。官職を独占する【門閥貴族】が形成され、【貴族制社会】が成立した。"},
  {"id": "whx35", "s": "wh", "lv": 1, "topic": "均田制", "q": "北魏の孝文帝が実施した均田制の目的と、その後の展開を述べよ。", "a": "戦乱で荒れた土地を農民に分け与えて耕作させ、【税収】を確保することを目的とした。成人男子のほか、妻や【奴婢】・耕牛にも土地を支給した。隋・唐に受け継がれ、【租調庸制】や【府兵制】の基盤となった。"},
  {"id": "whx36", "s": "wh", "lv": 2, "topic": "孝文帝の漢化政策", "q": "北魏の孝文帝がおこなった漢化政策の内容と、それがもたらした結果を述べよ。", "a": "都を平城から【洛陽】に移し、鮮卑の服装や言語を禁止するなど【漢化政策】を進めた。しかし、これに反発した北辺の軍人たちが【六鎮の乱】を起こし、北魏は東西に分裂した。"},
  {"id": "whx37", "s": "wh", "lv": 1, "topic": "中国への仏教伝来", "q": "魏晋南北朝時代に、仏教が中国に広まった過程を主な人物に触れて述べよ。", "a": "西域から来た【仏図澄】や【鳩摩羅什】が布教や仏典の翻訳をおこない、東晋の【法顕】はインドへ赴いて仏典を持ち帰った。北魏では【雲崗】や竜門に石窟寺院が造営された。"},
  {"id": "whx38", "s": "wh", "lv": 2, "topic": "江南の開発", "q": "魏晋南北朝時代に、長江下流域の江南で開発が進んだ理由を述べよ。", "a": "華北の戦乱を避けて多くの漢人が【江南】に移住し、【東晋】や南朝の諸王朝のもとで開発が進んだ。貴族を担い手とする優雅な【六朝文化】が栄え、のちに【経済の中心】が南に移る基礎となった。"},
  {"id": "whx39", "s": "wh", "lv": 3, "topic": "古代地中海の奴隷制", "q": "古代地中海世界で奴隷が果たした役割を、アテネとローマを対比して論ぜよ。", "a": "アテネでは【債務奴隷】が禁止されたのち、戦争捕虜や購入した奴隷が家内労働や鉱山で働き、市民が政治に参加する余裕を支えた。ローマではポエニ戦争以降、大量の捕虜奴隷が【ラティフンディア】で使役され、【スパルタクスの反乱】のような大反乱も起きた。"},
  {"id": "whx40", "s": "wh", "lv": 3, "topic": "東西ローマの命運", "q": "西ローマ帝国が早くに滅亡した一方、東ローマ帝国が長く存続した理由を論ぜよ。", "a": "西方では都市が衰え、【コロナトゥス】による自給的な経済が広がり、【ゲルマン人】の侵入に抵抗できなかった。東方は【コンスタンティノープル】を中心に商業と【貨幣経済】が維持され、強固な【官僚制】と皇帝権のもとで1000年以上存続した。"},
  {"id": "whx41", "s": "wh", "lv": 1, "topic": "科挙の創設", "q": "隋で始まった科挙は、それまでの官吏登用法と比べてどのような特徴をもっていたか。", "a": "九品中正にかわり、【隋】の文帝が【学科試験】によって広く人材を登用する制度として始めた。家柄によらず能力で官僚を選ぶ点が特徴で、宋代には皇帝みずからが試験官となる【殿試】が加わり、【皇帝】の権力を支える制度となった。"},
  {"id": "whx42", "s": "wh", "lv": 1, "topic": "唐の律令体制", "q": "唐が整えた律令体制とは、どのような仕組みで国家を運営する体制か。", "a": "刑法の【律】と行政法の【令】にもとづく統治体制。中央に【三省・六部】をおき、土地制度の【均田制】、税制の【租調庸制】、兵制の府兵制を組み合わせて運営された。"},
  {"id": "whx43", "s": "wh", "lv": 2, "topic": "両税法", "q": "唐の後半に両税法が施行された背景と、その課税の仕組みを述べよ。", "a": "均田制がくずれて農民の逃亡が増え、【租調庸制】が維持できなくなった。780年、宰相楊炎の献策で【両税法】が施行され、実際に所有する土地や資産に応じて【夏と秋の2回】課税した。これは【大土地所有】を事実上認める転換となった。"},
  {"id": "whx44", "s": "wh", "lv": 1, "topic": "安史の乱", "q": "8世紀半ばにおこった安史の乱は、唐の政治と社会にどのような影響を与えたか。", "a": "755年に【節度使】の安禄山らが起こした反乱で、唐はウイグルの援助を得て鎮圧した。乱後は節度使が地方で自立して【藩鎮】となり、中央の統制が弱まった。財政難を補うため【塩の専売】が強化された。"},
  {"id": "whx45", "s": "wh", "lv": 2, "topic": "国際都市長安", "q": "唐の都長安が国際都市として栄えた理由と、その文化の特徴を述べよ。", "a": "唐は周辺諸国と【冊封】関係を結び、【シルク=ロード】や海路を通じて各地から商人や留学生が集まった。長安には【ゾロアスター教】やネストリウス派キリスト教、マニ教の寺院が建てられ、国際色豊かな【貴族文化】が栄えた。"},
  {"id": "whx46", "s": "wh", "lv": 1, "topic": "宋の文治主義", "q": "宋の太祖（趙匡胤）が採用した文治主義とは、どのような政策か。", "a": "五代の武人政治の弊害をふまえ、【節度使】の権限を弱めて文官を重視した。【科挙】を整備して【殿試】を設け、皇帝による【君主独裁体制】を確立した。一方で軍事力が弱まり、北方民族の圧迫を受けた。"},
  {"id": "whx47", "s": "wh", "lv": 2, "topic": "王安石の新法", "q": "北宋の王安石がおこなった新法の目的と、その主な内容を述べよ。", "a": "財政難と軍事力の低下を克服する【富国強兵】を目的とした。中小農民に低利で資金を貸す【青苗法】、中小商人を助ける【市易法】、農閑期に農民を訓練する【保甲法】などを実施したが、【旧法党】の反対で激しい党争を招いた。"},
  {"id": "whx48", "s": "wh", "lv": 1, "topic": "宋代の経済発展", "q": "宋代の中国で経済が大きく発展したことについて、農業と商業の面から述べよ。", "a": "江南ではひでりに強い【占城稲】の導入などで稲作が発展し、「蘇湖熟すれば天下足る」といわれた。商業では草市や鎮などの商業都市が成長し、紙幣の【交子】が使われた。商人の同業組合【行】や手工業者の【作】も結成された。"},
  {"id": "whx49", "s": "wh", "lv": 2, "topic": "士大夫", "q": "宋代に新たな支配層となった士大夫とは、どのような人々か説明せよ。", "a": "唐末五代に門閥貴族が没落したのち、新興地主層の【形勢戸】が台頭した。彼らは【科挙】に合格して官僚となり、儒学的教養を身につけた【士大夫】として政治と文化を担った。官僚を出した家は【官戸】として特権を得た。"},
  {"id": "whx50", "s": "wh", "lv": 2, "topic": "朱子学", "q": "南宋の朱熹が大成した朱子学の特徴と、その後の東アジアへの影響を述べよ。", "a": "宇宙の原理である【理】と、万物を構成する【気】によって世界を説明し、君臣・華夷の区別を重んじる【大義名分論】を説いた。四書を重視し、明代には科挙の基準とされ、朝鮮や日本でも【官学】として受容された。"},
  {"id": "whx51", "s": "wh", "lv": 1, "topic": "宋と北方民族", "q": "北宋・南宋と北方民族の国家との関係について、遼と金を中心に述べよ。", "a": "北宋は契丹の【遼】と【澶淵の盟】を結び、毎年銀や絹を贈った。のち女真の【金】と結んで遼を滅ぼしたが、金に都の開封を攻略される【靖康の変】で滅亡した。江南に逃れた南宋は金に臣下の礼をとった。"},
  {"id": "whx52", "s": "wh", "lv": 3, "topic": "征服王朝の統治", "q": "遼と金が中国の農耕地帯を支配する際に用いた統治体制の特徴を論ぜよ。", "a": "遼は遊牧民を部族制で、農耕民を州県制で治める【二重統治体制】をとり、【契丹文字】を作って民族の独自性を保った。金も女真人を軍事・行政組織の【猛安・謀克】で、漢人を州県制で治めた。両国とも漢文化を受容しつつ、固有の文化と体制を維持しようとした。"},
  {"id": "whx53", "s": "wh", "lv": 2, "topic": "元の中国支配", "q": "元が中国を支配する際にとった統治の特徴を、民族の扱いに触れて述べよ。", "a": "要職はモンゴル人が独占し、中央アジア・西アジア出身の【色目人】が財務官僚として重用された。旧金領の住民は【漢人】、旧南宋の住民は【南人】とよばれた。【科挙】は一時停止され、儒学的教養をもつ士大夫は政治の中枢から遠ざけられた。"},
  {"id": "whx54", "s": "wh", "lv": 1, "topic": "元の滅亡", "q": "中国を支配した元が、14世紀に衰退して北方へ退いた理由を述べよ。", "a": "帝位争いが続き、チベット仏教への過剰な保護で財政が悪化した。不足を補うため紙幣の【交鈔】を乱発して物価が高騰し、民衆が困窮した。白蓮教徒を中心とする【紅巾の乱】がおこり、【朱元璋】が明を建てると、元は北方へ退いた。"},
  {"id": "whx55", "s": "wh", "lv": 1, "topic": "洪武帝の政策", "q": "明の洪武帝が皇帝独裁と農村支配を強化するためにおこなった政策を述べよ。", "a": "【中書省】を廃止して六部を皇帝直属とし、【皇帝独裁】を強化した。農村には【里甲制】をしき、租税台帳の【賦役黄冊】と土地台帳の【魚鱗図冊】を作成した。民衆教化のため六諭も定めた。"},
  {"id": "whx56", "s": "wh", "lv": 1, "topic": "鄭和の南海遠征", "q": "明の永楽帝が鄭和に命じた南海遠征の目的と、その影響を述べよ。", "a": "【永楽帝】はイスラーム教徒の宦官【鄭和】に大艦隊を率いさせ、東南アジアからアフリカ東岸まで派遣した。諸国に【朝貢】をうながし、明を中心とする国際秩序を広げることが目的だった。遠征の拠点となった【マラッカ】は中継港として発展した。"},
  {"id": "whx57", "s": "wh", "lv": 2, "topic": "明の海禁", "q": "明がおこなった海禁政策とはどのようなものか、その目的と結果を述べよ。", "a": "民間人の海外渡航や交易を禁止し、貿易を国家間の【朝貢貿易】に限定した政策。【倭寇】の取り締まりと国家による貿易独占が目的だった。しかし密貿易はやまず、16世紀に【後期倭寇】が活発化したため、明は【海禁】を緩和した。"},
  {"id": "whx58", "s": "wh", "lv": 2, "topic": "北虜南倭", "q": "16世紀の明を苦しめた「北虜南倭」とは何か、その影響とともに説明せよ。", "a": "北方では【モンゴル】の【アルタン=ハーン】が侵入をくり返し、北京を包囲した。南方の沿岸では中国人を主体とする【倭寇】が密貿易や略奪をおこなった。これらへの防衛費が明の【財政】を圧迫した。"},
  {"id": "whx59", "s": "wh", "lv": 1, "topic": "明清交替", "q": "17世紀前半に明が滅亡し、清が中国支配を始めた経緯を述べよ。", "a": "豊臣秀吉の朝鮮出兵への援軍や女真との戦いで財政が悪化し、重税で民衆が困窮した。1644年、【李自成の乱】で北京が陥落し明は滅亡した。山海関を守っていた【呉三桂】が清に降り、【清】が北京に入って中国支配を始めた。"},
  {"id": "whx60", "s": "wh", "lv": 1, "topic": "清の漢人統治", "q": "清が漢人を支配するために用いた懐柔策と威圧策について述べよ。", "a": "懐柔策として、要職に満洲人と漢人を同数任命する【満漢併用制】をとり、『四庫全書』などの大編纂事業で知識人を優遇した。威圧策として、満洲人の髪型である【辮髪】を強制し、【文字の獄】や禁書で反清思想を弾圧した。"},
  {"id": "whx61", "s": "wh", "lv": 2, "topic": "康熙帝", "q": "清の康熙帝が支配を安定させるためにおこなった内政・外交の政策を述べよ。", "a": "漢人武将が南方で起こした【三藩の乱】を鎮圧し、【鄭氏台湾】を降して中国全土を平定した。北方ではロシアと【ネルチンスク条約】を結んで国境を定め、通商を認めた。"},
  {"id": "whx62", "s": "wh", "lv": 2, "topic": "地丁銀制", "q": "清代に実施された地丁銀制とは、どのような税制か、その影響とともに述べよ。", "a": "明の一条鞭法を受けつぎ、【人頭税】（丁税）を【土地税】（地税）にくりこんで一本化した税制。康熙帝が丁税額を固定したのち、【雍正帝】の時代に全国に広まった。人頭税が事実上廃止され、【人口】の急増を後押しした。"},
  {"id": "whx63", "s": "wh", "lv": 3, "topic": "清の藩部統治", "q": "清はモンゴル・チベット・新疆などの地域をどのように統治したかを論ぜよ。", "a": "これらの地域を【藩部】とし、【理藩院】に管轄させた。現地の有力者に自治を認め、モンゴルの王侯やチベット仏教の権威を利用する間接統治をおこなった。清の皇帝はモンゴルに対しては遊牧君主の【ハーン】として、チベットに対しては仏教の保護者としてふるまった。"},
  {"id": "whx64", "s": "wh", "lv": 1, "topic": "新羅の統一", "q": "7世紀に朝鮮半島を統一した新羅について、統一の過程と社会の特徴を述べよ。", "a": "新羅は唐と結んで【百済】と【高句麗】を滅ぼし、その後唐の勢力を排除して半島を統一した。唐の律令制を取り入れる一方、血統による厳格な身分制度である【骨品制】が社会を支え、都の慶州では【仏教】文化が栄えた。"},
  {"id": "whx65", "s": "wh", "lv": 2, "topic": "高麗の文化", "q": "10世紀に朝鮮半島で成立した高麗の時代に生まれた文化について述べよ。", "a": "仏教が国家の保護を受け、モンゴルの侵入からの加護を願って【高麗版大蔵経】が刊行された。世界最古級の【金属活字】も作られ、宋の影響を受けた【高麗青磁】が名品として知られた。"},
  {"id": "whx66", "s": "wh", "lv": 1, "topic": "朝鮮王朝", "q": "14世紀末に朝鮮半島で成立した朝鮮王朝の政治と文化について述べよ。", "a": "倭寇の撃退で名声を得た【李成桂】が建てた。【朱子学】を官学とし、科挙で官僚を選んだが、官僚を輩出した【両班】が特権身分となった。15世紀に世宗は表音文字の【訓民正音】（ハングル）を制定した。"},
  {"id": "whx67", "s": "wh", "lv": 2, "topic": "突厥とウイグル", "q": "6〜9世紀にモンゴル高原で活躍した突厥とウイグルについて述べよ。", "a": "【突厥】は6世紀に柔然を倒して強大化し、独自の【突厥文字】を作った。8世紀には【ウイグル】が台頭し、【安史の乱】で唐を援助した。ウイグルはソグド人と結びつき、【マニ教】を信仰した。"},
  {"id": "whx68", "s": "wh", "lv": 2, "topic": "ソグド人", "q": "ソグド人が内陸アジアの東西交流において果たした役割を述べよ。", "a": "中央アジアの【サマルカンド】などのオアシス都市を拠点に、【シルク=ロード】の交易で活躍したイラン系の民族。遊牧国家や唐と結びついて活動し、【ソグド文字】は【ウイグル文字】の起源となった。"},
  {"id": "whx69", "s": "wh", "lv": 3, "topic": "遊牧国家とオアシス都市", "q": "内陸アジアにおいて、遊牧国家とオアシス都市がどのような関係を結んでいたかを論ぜよ。", "a": "【遊牧国家】は騎馬軍事力でオアシス都市を保護・支配し、オアシス都市は【隊商交易】の利益や農産物を提供した。遊牧国家は中国王朝から絹などを【貢納】や交易で獲得し、オアシスの商人がそれを西方へ運んだ。両者は互いに依存する【共生関係】にあった。"},
  {"id": "whx70", "s": "wh", "lv": 3, "topic": "唐宋変革", "q": "唐から宋の時代に中国社会がどのように変わったのか、支配層と経済の変化から論ぜよ。", "a": "唐末の戦乱で【門閥貴族】が没落し、宋では【科挙】出身の官僚と新興地主の【形勢戸】が支配層となった。土地制度は均田制から小作人の【佃戸】を使う地主制に移り、商業では坊市制がくずれて【貨幣経済】が発展した。"},
  {"id": "whx71", "s": "wh", "lv": 3, "topic": "明清の貿易体制", "q": "明から清にかけて、中国の対外貿易体制がどのように変化したかを論ぜよ。", "a": "明初は【海禁】と【朝貢貿易】によって国家が貿易を独占したが、16世紀後半に海禁を緩めて民間貿易を許した。清は台湾の鄭氏を降すと海禁を解き、民間の【互市】を広く認めたが、18世紀半ばにはヨーロッパとの貿易を【広州】一港に限定した。"},
  {"id": "whx72", "s": "wh", "lv": 1, "topic": "宋代の文化", "q": "宋代の中国文化の特徴を、印刷などの技術と美術の面から述べよ。", "a": "【木版印刷】が普及して書物が広まり、【羅針盤】や【火薬】が実用化された。絵画では宮廷画家による院体画と、士大夫による【文人画】が描かれ、陶磁器では【青磁】や白磁が作られた。"},
  {"id": "whx73", "s": "wh", "lv": 1, "topic": "明代の文化", "q": "明代後期の中国文化の特徴を、儒学などの学問と庶民文化の面から述べよ。", "a": "【王守仁】（王陽明）は知識と実践の一致を説く【陽明学】をおこした。実用的な学問も重視され、『本草綱目』や『天工開物』が著された。庶民の間では『西遊記』『水滸伝』などの口語【小説】が広く読まれた。"},
  {"id": "whx74", "s": "wh", "lv": 2, "topic": "イエズス会宣教師", "q": "明末清初に中国で活動したイエズス会宣教師の役割と、その後の布教禁止について述べよ。", "a": "【マテオ=リッチ】は世界地図「坤輿万国全図」を作り、徐光啓と『幾何原本』を訳した。【アダム=シャール】らは暦の作成に関わった。のち布教方法をめぐる【典礼問題】がおこり、【雍正帝】はキリスト教の布教を禁止した。"},
  {"id": "whx75", "s": "wh", "lv": 2, "topic": "考証学", "q": "清代の中国で考証学が盛んになった背景と、その学風の特徴を述べよ。", "a": "明末清初の【顧炎武】らは、空論におちいった陽明学を批判し、経書を実証的に研究する学風をおこした。清の【文字の獄】による思想統制で政治的な議論が難しくなると、学者は古典の文献研究に向かい、【考証学】が隆盛した。"},
  {"id": "whx76", "s": "wh", "lv": 1, "topic": "隋の滅亡", "q": "南北朝を統一した隋が、わずか30年ほどで滅亡した理由を述べよ。", "a": "第2代の【煬帝】は【大運河】の建設などの大土木事業や、3度にわたる【高句麗遠征】をおこなった。重い負担に苦しむ民衆の反乱が各地でおこり、隋は統一から約30年で滅亡した。"},
  {"id": "whx77", "s": "wh", "lv": 2, "topic": "冊封体制", "q": "中国王朝が周辺諸国と結んだ冊封体制とは、どのような国際関係か。", "a": "中国皇帝が周辺諸国の君主に【官爵】を与えて君臣関係を結び、君主は皇帝に【朝貢】した。皇帝の徳が周辺に及ぶとする【中華思想】にもとづく秩序で、周辺国は権威の承認と【交易】の利益を得た。"},
  {"id": "whx78", "s": "wh", "lv": 1, "topic": "白蓮教徒の乱", "q": "18世紀末に清でおこった白蓮教徒の乱の背景と、その影響を述べよ。", "a": "18世紀の【人口】急増で耕地が不足し、山間部に移住した貧民が【白蓮教】を信仰して反乱をおこした。正規軍の【八旗】は役に立たず、【郷勇】とよばれる義勇軍によって鎮圧された。財政も悪化し、清の衰退が始まった。"},
  {"id": "whx79", "s": "wh", "lv": 3, "topic": "明清の江南経済", "q": "明代後期から清代にかけて、長江流域の経済構造がどのように変化したかを論ぜよ。", "a": "長江下流域では【綿織物】や【生糸】などの家内手工業が発達し、商品作物の栽培が広がった。そのため穀倉地帯は中流域に移り「【湖広熟すれば天下足る】」といわれた。【山西商人】や【徽州商人】など、遠隔地商業で富を得た商人が活躍した。"},
  {"id": "whx80", "s": "wh", "lv": 1, "topic": "イスラーム教の成立", "q": "7世紀にムハンマドが創始したイスラーム教の特徴と、その成立の過程を述べよ。", "a": "【メッカ】の商人ムハンマドが唯一神【アッラー】の啓示を受けたとして始めた。神の前での信者の平等を説き、偶像崇拝を厳しく禁じた。迫害を受けて622年にメディナへ移住した【ヒジュラ】（聖遷）がイスラーム暦の元年とされ、教えは聖典【コーラン】にまとめられた。"},
  {"id": "whx81", "s": "wh", "lv": 1, "topic": "正統カリフ時代", "q": "ムハンマドの死後、正統カリフ時代にイスラーム勢力がどのように拡大したかを述べよ。", "a": "信者の合意で選ばれた【カリフ】が共同体を指導した。【ジハード】（聖戦）による大征服でビザンツ帝国からシリアやエジプトを奪い、イランの【ササン朝】を滅ぼした。征服地の異教徒には人頭税の【ジズヤ】と地租の【ハラージュ】を課した。"},
  {"id": "whx82", "s": "wh", "lv": 2, "topic": "スンナ派とシーア派", "q": "イスラーム教のスンナ派とシーア派は、どのような点で考え方が異なるかを説明せよ。", "a": "【シーア派】は第4代正統カリフの【アリー】とその子孫だけを正統な指導者（イマーム）とする。一方、多数派の【スンナ派】は歴代カリフの権威を認め、ムハンマドの言行（スンナ）に従う共同体の合意を重視する。"},
  {"id": "whx83", "s": "wh", "lv": 2, "topic": "知恵の館と翻訳", "q": "アッバース朝の時代に学問が発達した理由と、それがヨーロッパに与えた影響を述べよ。", "a": "都【バグダード】の【知恵の館】でギリシア語文献がアラビア語に翻訳され、哲学・医学・天文学が発達した。【イブン=シーナー】の『医学典範』などは、のちに【ラテン語】に翻訳されて西欧に伝わり、【12世紀ルネサンス】をもたらした。"},
  {"id": "whx84", "s": "wh", "lv": 2, "topic": "3カリフの並立", "q": "10世紀のイスラーム世界で、3人のカリフが並び立った経緯を述べよ。", "a": "アッバース朝のカリフに対し、北アフリカに興ったシーア派の【ファーティマ朝】の君主がカリフを称し、イベリア半島の【後ウマイヤ朝】の君主もカリフを称した。さらに、バグダードはシーア派の【ブワイフ朝】に占領され、アッバース朝カリフの政治的権威は低下した。"},
  {"id": "whx85", "s": "wh", "lv": 2, "topic": "セルジューク朝", "q": "11世紀に成立したセルジューク朝が、イスラーム世界で果たした役割について述べよ。", "a": "トルコ系の【セルジューク朝】は1055年にバグダードに入り、カリフから【スルタン】の称号を得て政治権力を握った。アナトリアに進出してビザンツ帝国を圧迫し、これが【十字軍】のきっかけとなった。軍人に徴税権を与える【イクター制】を広く施行した。"},
  {"id": "whx86", "s": "wh", "lv": 3, "topic": "イクター制", "q": "イスラーム世界におけるイクター制の成立と、その特徴を西欧の封建制と比べて論ぜよ。", "a": "【ブワイフ朝】が軍人に俸給のかわりに土地の【徴税権】を与えたことで始まり、【セルジューク朝】が広く施行した。現金収入の不足に対応して軍事力を維持する制度だった。西欧の封建制と異なり、原則として【世襲】は認められず、国家による土地支配が維持された。"},
  {"id": "whx87", "s": "wh", "lv": 1, "topic": "オスマン帝国の拡大", "q": "オスマン帝国が14〜16世紀に勢力を拡大した過程を、主な君主に触れて述べよ。", "a": "バルカン半島へ進出し、1453年に【メフメト2世】が【コンスタンティノープル】を攻略してビザンツ帝国を滅ぼした。セリム1世はマムルーク朝を滅ぼして聖地を支配下におき、【スレイマン1世】の時代には【ウィーン】を包囲するなど最盛期を迎えた。"},
  {"id": "whx88", "s": "wh", "lv": 2, "topic": "オスマン帝国の統治", "q": "オスマン帝国は、多民族・多宗教の人々をどのように統治したかを述べよ。", "a": "キリスト教徒やユダヤ教徒の宗教共同体【ミッレト】に、納税と引きかえに自治を認めた。キリスト教徒の子弟を強制的に集める【デヴシルメ】で官僚や常備歩兵軍の【イェニチェリ】を養成し、騎士には【ティマール制】で徴税権を与えた。"},
  {"id": "whx89", "s": "wh", "lv": 2, "topic": "サファヴィー朝", "q": "16世紀初めにイランで成立したサファヴィー朝の特徴を述べよ。", "a": "神秘主義教団の長イスマーイールが建国し、【シーア派】を国教としてスンナ派のオスマン帝国と対立した。君主はイラン伝統の【シャー】の称号を用いた。【アッバース1世】は新都【イスファハーン】を建設し、「世界の半分」といわれるほど繁栄した。"},
  {"id": "whx90", "s": "wh", "lv": 1, "topic": "アクバルの統治", "q": "ムガル帝国のアクバルが、多数のヒンドゥー教徒を統治するためにおこなった政策を述べよ。", "a": "【アクバル】は非ムスリムに課される人頭税の【ジズヤ】を廃止し、ヒンドゥー教徒の【ラージプート】の王女と結婚するなど融和を図った。官僚の位階に応じて給与と保持すべき騎兵数を定める【マンサブダール制】で支配体制を整えた。"},
  {"id": "whx91", "s": "wh", "lv": 2, "topic": "アウラングゼーブ", "q": "ムガル帝国のアウラングゼーブ帝の宗教政策は、帝国にどのような影響を与えたか。", "a": "熱心なスンナ派ムスリムの【アウラングゼーブ】は、【ジズヤ】を復活させるなどヒンドゥー教徒を圧迫した。そのため【ラージプート】やデカン高原の【マラーター】、パンジャーブの【シク教徒】の反抗を招き、彼の死後、帝国は急速に衰退した。"},
  {"id": "whx92", "s": "wh", "lv": 2, "topic": "インド=イスラーム文化", "q": "ムガル帝国時代に生まれたインド=イスラーム文化の特徴を述べよ。", "a": "イスラーム文化とインドの文化が融合した文化。建築ではシャー=ジャハーンが造った【タージ=マハル】、絵画ではペルシアの影響を受けた【細密画】が発達した。言語では【ウルドゥー語】が生まれ、宗教ではナーナクが【シク教】を開いた。"},
  {"id": "whx93", "s": "wh", "lv": 1, "topic": "インドのイスラーム化", "q": "10世紀以降、北インドにイスラーム教が広まった過程を述べよ。", "a": "10世紀末から【ガズナ朝】や【ゴール朝】が北インドに侵入した。13世紀には【奴隷王朝】がデリーを都として成立し、以後の五王朝は【デリー=スルタン朝】とよばれた。神との合一をめざす【神秘主義】（スーフィズム）の聖者の活動で、民衆にも改宗が広まった。"},
  {"id": "whx94", "s": "wh", "lv": 3, "topic": "東南アジアのイスラーム化", "q": "13世紀以降、東南アジアの島嶼部にイスラーム教が広まった経緯を論ぜよ。", "a": "インド洋交易に従事する【ムスリム商人】の来航とともに、港市の支配者が改宗していった。15世紀には【マラッカ王国】が国王の改宗によってイスラーム化し、交易の拠点として布教の中心となった。その後、スマトラの【アチェ王国】やジャワの【マタラム王国】などのイスラーム国家が成立した。"},
  {"id": "whx95", "s": "wh", "lv": 1, "topic": "アンコール朝", "q": "9世紀以降カンボジアで栄えたアンコール朝の特徴を、建造物に触れて述べよ。", "a": "クメール人が建てた王朝で、インドから伝わった【ヒンドゥー教】や仏教の影響を受けた。12世紀にはヒンドゥー教寺院の【アンコール=ワット】が造営され、のちに仏教色の強い都城【アンコール=トム】も建てられた。"},
  {"id": "whx96", "s": "wh", "lv": 2, "topic": "シュリーヴィジャヤ", "q": "7世紀にスマトラ島を中心に栄えたシュリーヴィジャヤが繁栄した理由を述べよ。", "a": "【マラッカ海峡】を押さえる位置にあり、中国とインドを結ぶ【海上交易】の中継で栄えた【港市国家】である。唐の僧【義浄】がインドへの往復で滞在して記録を残したように、仏教が盛んだった。"},
  {"id": "whx97", "s": "wh", "lv": 2, "topic": "東南アジアのインド化", "q": "東南アジアの「インド化」とはどのような現象か、具体例を挙げて述べよ。", "a": "交易を通じて、インドから【ヒンドゥー教】や【仏教】、サンスクリット語、神聖な王権の観念などが受け入れられた現象。ジャワ島の【シャイレンドラ朝】は大乗仏教の寺院【ボロブドゥール】を建設した。"},
  {"id": "whx98", "s": "wh", "lv": 2, "topic": "ベトナムの諸王朝", "q": "中国の支配から独立したベトナムの諸王朝と、中国との関係について述べよ。", "a": "10世紀に独立し、11世紀に【李朝】が大越国を建てた。【陳朝】は元の侵攻を撃退し、漢字をもとに独自の文字【チュノム】（字喃）を作った。15世紀の【黎朝】は明の支配を退けたのち、明の制度を取り入れて中央集権化を進めた。"},
  {"id": "whx99", "s": "wh", "lv": 1, "topic": "上座部仏教の広がり", "q": "東南アジアの大陸部に、スリランカから上座部仏教が広まったことについて述べよ。", "a": "11世紀以降、ビルマの【パガン朝】やタイの【スコータイ朝】、のちの【アユタヤ朝】で、スリランカから伝わった【上座部仏教】が信仰された。上座部仏教は王権と結びつき、民衆の間にも定着した。"},
  {"id": "whx100", "s": "wh", "lv": 1, "topic": "西アフリカの諸王国", "q": "西アフリカのガーナ王国やマリ王国が繁栄した理由を述べよ。", "a": "サハラ砂漠をこえる【サハラ縦断交易】で、西アフリカの【金】と北方の【岩塩】を交換して栄えた。マリ王国の【マンサ=ムーサ】はメッカ巡礼で大量の金を使い、その富を広く知らせた。【トンブクトゥ】は交易と学問の中心となった。"},
  {"id": "whx101", "s": "wh", "lv": 2, "topic": "スワヒリ文化", "q": "東アフリカ沿岸の海港都市の繁栄と、そこで生まれた文化について述べよ。", "a": "【マリンディ】や【キルワ】などの海港都市が、【ムスリム商人】による【インド洋交易】で栄えた。現地のバントゥー系言語にアラビア語の語彙が加わった【スワヒリ語】が共通語として広まった。"},
  {"id": "whx102", "s": "wh", "lv": 2, "topic": "大ジンバブエ", "q": "アフリカ南部のジンバブエ高原で栄えた国家と、大ジンバブエ遺跡について述べよ。", "a": "ショナ人の国家が【金】や象牙の輸出で栄え、巨大な石造建築の【大ジンバブエ遺跡】を残した。遺跡からは【インド洋交易】を通じてもたらされた中国の陶磁器も出土している。15世紀以降は【モノモタパ王国】が栄えた。"},
  {"id": "whx103", "s": "wh", "lv": 3, "topic": "アフリカのイスラーム化", "q": "中世のアフリカで、イスラーム教が受容された経路と、その特徴を論ぜよ。", "a": "西アフリカでは【サハラ縦断交易】を通じてムスリム商人が来訪し、【マリ王国】や【ソンガイ王国】の支配層が改宗した。東アフリカ沿岸では【インド洋交易】を通じてイスラームが浸透し、【スワヒリ文化】が生まれた。いずれも交易を担う商人と、王権や都市の支配層を通じて広まった。"},
  {"id": "whx104", "s": "wh", "lv": 1, "topic": "カールの戴冠", "q": "カール大帝の戴冠は、ヨーロッパ史においてどのような意義をもつか述べよ。", "a": "800年、教皇【レオ3世】がフランク王【カール大帝】にローマ皇帝の冠を与えた。これにより【ローマ=カトリック教会】とゲルマン人の国家が結びつき、ビザンツ帝国から自立した【西ヨーロッパ世界】が成立した。"},
  {"id": "whx105", "s": "wh", "lv": 1, "topic": "封建的主従関係", "q": "中世西ヨーロッパの封建的主従関係とは、どのような関係かを説明せよ。", "a": "主君が家臣に【封土】を与えて保護し、家臣は主君に【軍事的奉仕】の義務を負う関係。双方が義務を負う【双務的契約】である点が特徴で、一人の家臣が複数の主君に仕えることもあった。"},
  {"id": "whx106", "s": "wh", "lv": 1, "topic": "荘園と農奴", "q": "中世西ヨーロッパの荘園において、農民はどのような立場におかれていたか。", "a": "農民の多くは移動の自由のない【農奴】で、領主直営地での【賦役】と、保有地からの生産物を納める【貢納】の義務を負った。結婚税や死亡税も課された。領主は国王の役人の立ち入りや課税を拒む【不輸不入権】をもち、荘園を支配した。"},
  {"id": "whx107", "s": "wh", "lv": 2, "topic": "叙任権闘争", "q": "叙任権闘争とはどのような争いか、その経過と結果を述べよ。", "a": "聖職者の任命権をめぐる教皇と神聖ローマ皇帝の争い。教皇【グレゴリウス7世】が皇帝【ハインリヒ4世】を破門し、皇帝が教皇に謝罪する【カノッサの屈辱】がおこった。1122年の【ヴォルムス協約】で、叙任権は教皇がもつことが確認された。"},
  {"id": "whx108", "s": "wh", "lv": 2, "topic": "中世都市の自治", "q": "中世西ヨーロッパで都市が発達した背景と、都市の自治について述べよ。", "a": "農業生産力の向上で余剰生産物が生まれ、【商業の復活】が進んで都市が発達した。都市は皇帝や国王から【特許状】を得て自治権を獲得した。北イタリアの【コムーネ】やドイツの【自由都市】が成立し、【ハンザ同盟】などの都市同盟も結ばれた。"},
  {"id": "whx109", "s": "wh", "lv": 2, "topic": "ギルド", "q": "中世都市のギルドとはどのような組織か、その特徴と都市政治への影響を述べよ。", "a": "商人や手工業者の同業組合。【同職ギルド】では親方だけが組合員となり、職人や徒弟を従えた。自由な競争を禁止し、製品の品質・価格・生産量を統制した。市政を独占した【商人ギルド】に対し、手工業者は【ツンフト闘争】をおこして市政への参加を実現した。"},
  {"id": "whx110", "s": "wh", "lv": 1, "topic": "黒死病", "q": "14世紀にヨーロッパで流行した黒死病は、社会にどのような影響を与えたか。", "a": "人口の約3分の1が失われ、労働力不足から農民の地位が向上し、イギリスでは【独立自営農民】（ヨーマン）が成長した。領主が再び束縛を強めると【ジャックリーの乱】や【ワット=タイラーの乱】がおこり、【封建社会】は解体に向かった。"},
  {"id": "whx111", "s": "wh", "lv": 2, "topic": "百年戦争", "q": "百年戦争の原因と、それが英仏両国に与えた影響を述べよ。", "a": "フランスの王位継承問題と、毛織物産業の盛んな【フランドル地方】の支配をめぐって英仏が争った。【ジャンヌ=ダルク】の活躍もありフランスが勝利した。戦争で両国の諸侯や騎士が没落し、【中央集権化】が進んだ。イギリスではその後【バラ戦争】がおこった。"},
  {"id": "whx112", "s": "wh", "lv": 1, "topic": "教皇権の衰退", "q": "13世紀末以降、ローマ教皇の権威が衰退していった経過を述べよ。", "a": "フランス王【フィリップ4世】が教皇ボニファティウス8世をとらえる【アナーニ事件】がおこった。その後、教皇庁が南フランスのアヴィニョンに移される【教皇のバビロン捕囚】が続き、さらに複数の教皇が並び立つ【教会大分裂】がおこった。"},
  {"id": "whx113", "s": "wh", "lv": 2, "topic": "ビザンツ帝国", "q": "ビザンツ帝国の政治体制の特徴と、その文化について述べよ。", "a": "皇帝が政治と宗教の両方の最高権力をもつ【皇帝教皇主義】をとった。7世紀以降、異民族の侵入に対して【軍管区制】（テマ制）をしき、【屯田兵制】で防衛した。ギリシア正教とギリシア古典文化を融合した文化が栄え、【ハギア=ソフィア聖堂】が建てられた。"},
  {"id": "whx114", "s": "wh", "lv": 2, "topic": "東西教会の分裂", "q": "キリスト教会がローマ=カトリック教会とギリシア正教会に分裂した経緯を述べよ。", "a": "726年、ビザンツ皇帝レオン3世が【聖像禁止令】を出すと、ゲルマン人への布教に聖像を用いていたローマ教会が反発し、フランク王国に接近した。両教会の対立は深まり、1054年に【ローマ=カトリック教会】と【ギリシア正教会】に分裂した。"},
  {"id": "whx115", "s": "wh", "lv": 1, "topic": "ノルマン人の移動", "q": "9〜11世紀のノルマン人の移動は、ヨーロッパ各地にどのような国家を生んだか。", "a": "北フランスに【ノルマンディー公国】を建て、そこから【ノルマン=コンクェスト】でイングランドを征服した。南イタリアとシチリアには【両シチリア王国】を建て、東ではルーシの一派が【ノヴゴロド国】を建てた。"},
  {"id": "whx116", "s": "wh", "lv": 2, "topic": "イギリス議会の起源", "q": "中世イングランドで議会政治の基礎が形成された過程を述べよ。", "a": "ジョン王は貴族らの要求で1215年に【大憲章】（マグナ=カルタ）を認め、課税には貴族の同意が必要とされた。13世紀後半の【シモン=ド=モンフォール】の議会を経て、エドワード1世が【模範議会】を招集した。14世紀には貴族院と庶民院の【二院制】が成立した。"},
  {"id": "whx117", "s": "wh", "lv": 3, "topic": "中世の農業革命", "q": "11〜13世紀の西ヨーロッパで農業生産力が向上した理由と、その社会的影響を論ぜよ。", "a": "秋耕地・春耕地・休耕地を輪作する【三圃制】や、牛馬に引かせる【重量有輪犂】の普及で生産力が高まり、人口が増加した。余剰生産物は【商業の復活】と都市の発達を促し、人口増加はエルベ川以東への【東方植民】や十字軍など、ヨーロッパの対外的な拡大をもたらした。"},
  {"id": "whx118", "s": "wh", "lv": 3, "topic": "ビザンツ帝国の変容", "q": "11世紀以降のビザンツ帝国で、国家体制がどのように変化したかを論ぜよ。", "a": "テマ制を支えた【屯田兵】などの自由農民が没落し、軍管区制はくずれた。帝国は有力者に軍役と引きかえに土地の管理と徴税を委ねる【プロノイア制】を導入し、地方の有力者が自立して【封建化】が進んだ。【第4回十字軍】によるコンスタンティノープル占領で、帝国はさらに衰えた。"},
  {"id": "whx119", "s": "wh", "lv": 3, "topic": "レコンキスタ", "q": "イベリア半島でのレコンキスタの過程と、それが近世スペインの性格に与えた影響を論ぜよ。", "a": "キリスト教諸国がイスラーム勢力から領土を奪回する【レコンキスタ】が進み、【カスティリャ】と【アラゴン】が統合してスペイン王国が成立した。1492年に【グラナダ】を攻略して完了した。強いカトリック信仰が王権と結びつき、ユダヤ教徒の追放や、新大陸への進出と布教につながった。"},
  {"id": "whx120", "s": "wh", "lv": 1, "topic": "マムルーク朝", "q": "13世紀にエジプトで成立したマムルーク朝が、イスラーム世界で果たした役割を述べよ。", "a": "トルコ系の軍人奴隷【マムルーク】が建てた王朝で、【モンゴル軍】の侵攻を撃退し、十字軍勢力も一掃した。首都【カイロ】はイスラーム世界の政治・経済・文化の中心として栄え、【カーリミー商人】が香辛料交易で活躍した。"},
  {"id": "whx121", "s": "wh", "lv": 1, "topic": "ティムール朝", "q": "14世紀後半に中央アジアで成立したティムール朝について述べよ。", "a": "【ティムール】はモンゴル帝国の再興をめざして中央アジアから西アジアに大帝国を築き、【アンカラの戦い】でオスマン帝国を破った。都の【サマルカンド】は交易と文化の中心として栄え、細密画などの【トルコ=イスラーム文化】が発達した。"}
];
